describe('refNo', () => {
  it('is QR-yymmdd-XXXXXX from the Manila date and the unambiguous alphabet', () => {
    const r = Q.refNo(NOW, () => Buffer.from([0, 1, 2, 3, 4, 5]));
    assert.equal(r, 'QR-261021-ABCDEF');
    assert.match(Q.refNo(NOW), /^QR-261021-[A-HJKMNP-Z2-9]{6}$/);
    for (let i = 0; i < 200; i++) assert.ok(!/[01OIL]/.test(Q.refNo(NOW).slice(10)), 'ambiguous character');
  });
  it('uses the MANILA date, not the UTC date (02:00 Manila on the 21st is still the 20th in UTC)', () => {
    const utcPrevDay = Date.UTC(2026, 9, 20, 18, 0, 0);       // 02:00 Manila, 21 Oct
    assert.match(Q.refNo(utcPrevDay), /^QR-261021-/);
    const utcLateEvening = Date.UTC(2026, 9, 21, 17, 0, 0);   // 01:00 Manila, 22 Oct
    assert.match(Q.refNo(utcLateEvening), /^QR-261022-/);
  });
  it('matches the pattern qrAdminDelete accepts', () => {
    assert.match(Q.refNo(NOW), /^QR-\d{6}-[A-Z2-9]{6}$/);
  });
});

describe('validateIntake — spec §4.3', () => {
  const good = () => ({ need: 'equipment', useFor: 'restaurant_cafe', entityType: 'private', targetDate: '2026-12-01', address: '12 Rizal St, Quezon City' });
  const v = (o) => Q.validateIntake(o, NOW);

  it('accepts a complete intake and returns only the clean keys', () => {
    const r = v(good());
    assert.equal(r.ok, true, r.errors.join('|'));
    assert.deepEqual(r.clean, { need: 'equipment', useFor: 'restaurant_cafe', entityType: 'private', targetDate: '2026-12-01', targetFlexible: false, address: '12 Rizal St, Quezon City' });
  });
  it('every select must be one of its option values', () => {
    for (const k of ['need', 'useFor', 'entityType']) {
      assert.equal(v({ ...good(), [k]: 'bogus' }).ok, false, k);
      assert.equal(v({ ...good(), [k]: undefined }).ok, false, k);
      assert.equal(v({ ...good(), [k]: 5 }).ok, false, k);
    }
  });
  it('"other" requires its text (<= 120), and the text is refused when "other" is not chosen', () => {
    assert.equal(v({ ...good(), need: 'other' }).ok, false);
    assert.equal(v({ ...good(), need: 'other', needOther: '   ' }).ok, false);
    const ok = v({ ...good(), need: 'other', needOther: ' Bakery oven  ' });
    assert.equal(ok.ok, true);
    assert.equal(ok.clean.needOther, 'Bakery oven');
    assert.equal(v({ ...good(), need: 'other', needOther: 'x'.repeat(121) }).ok, false);
    assert.equal(v({ ...good(), need: 'equipment', needOther: 'sneaky' }).ok, false);
    assert.equal(v({ ...good(), useFor: 'other' }).ok, false);
    assert.equal(v({ ...good(), useFor: 'other', useForOther: 'Food truck' }).ok, true);
    assert.equal(v({ ...good(), useFor: 'home', useForOther: 'x' }).ok, false);
    assert.equal(v({ ...good(), need: 'equipment', needOther: '' }).ok, true);          // a blank "other" is just absent
  });
  it('target date: a real date from today (Manila) to three years out', () => {
    assert.equal(v({ ...good(), targetDate: '2026-10-21' }).ok, true);                  // today
    assert.equal(v({ ...good(), targetDate: '2026-10-20' }).ok, false);                 // yesterday
    assert.equal(v({ ...good(), targetDate: '2029-10-21' }).ok, true);                  // exactly three years
    assert.equal(v({ ...good(), targetDate: '2029-10-22' }).ok, false);
    for (const bad of ['2026-02-30', '2026-13-01', '21-10-2026', '2026-1-1', 'tomorrow', 20261201, '']) assert.equal(v({ ...good(), targetDate: bad }).ok, false, String(bad));
  });
  it('the date window is anchored to the MANILA date (01:00 Manila on the 21st is still the 20th in UTC)', () => {
    const t = Date.UTC(2026, 9, 20, 17, 0, 0);
    assert.equal(Q.validateIntake({ ...good(), targetDate: '2026-10-21' }, t).ok, true);
    assert.equal(Q.validateIntake({ ...good(), targetDate: '2026-10-20' }, t).ok, false);   // past in Manila although it is "today" in UTC
  });
  it('"Not sure yet": flexible with no date is fine; flexible WITH a date is an error; neither is an error', () => {
    const r = v({ need: 'equipment', useFor: 'home', entityType: 'private', targetFlexible: true, targetDate: null, address: '12 Rizal St' });
    assert.equal(r.ok, true);
    assert.equal(r.clean.targetDate, null);
    assert.equal(r.clean.targetFlexible, true);
    assert.equal(v({ ...good(), targetFlexible: true }).ok, false);
    const { targetDate, ...none } = good();
    assert.equal(v(none).ok, false);
    assert.equal(v({ ...good(), targetFlexible: 'yes' }).ok, false);
  });
  it('address 5..500 (multiline kept), notes optional <= 1000 and omitted when blank', () => {
    assert.equal(v({ ...good(), address: '1234' }).ok, false);
    assert.equal(v({ ...good(), address: 'x'.repeat(501) }).ok, false);
    assert.equal(v({ ...good(), address: 'Unit 4\nBlock 2' }).clean.address, 'Unit 4\nBlock 2');
    assert.equal(v({ ...good(), notes: 'x'.repeat(1001) }).ok, false);
    assert.equal(v({ ...good(), notes: '  ' }).clean.notes, undefined);
    assert.equal(v({ ...good(), notes: 'Call after 5 pm' }).clean.notes, 'Call after 5 pm');
    assert.equal(v({ ...good(), notes: 12 }).ok, false);
  });
  it('control characters are stripped from every text field', () => {
    const r = v({ ...good(), address: 'Rizal\u0000 St\u0007, QC' });
    assert.equal(r.clean.address, 'Rizal St, QC');
  });
  it('an unknown key is an error and is named', () => {
    const r = v({ ...good(), isAdmin: true });
    assert.equal(r.ok, false);
    assert.ok(r.errors.some((e) => e.indexOf('Unknown field') === 0));
  });
  it('rubbish input never throws', () => {
    for (const x of [null, undefined, 5, 'x', [], [1]]) assert.equal(v(x).ok, false);
  });
});

describe('validateContact + normaliseMobile — R5', () => {
  const good = () => ({ name: 'Juan Dela Cruz', mobile: '0917 123 4567', email: 'juan@example.com', company: 'JDC Foods' });
  it('accepts a complete contact; the mobile is stored normalised as 09XXXXXXXXX', () => {
    const r = Q.validateContact(good());
    assert.equal(r.ok, true);
    assert.deepEqual(r.clean, { name: 'Juan Dela Cruz', mobile: '09171234567', email: 'juan@example.com', company: 'JDC Foods' });
  });
  it('every accepted mobile form normalises to 09171234567', () => {
    for (const m of ['0917 123 4567', '+63 917 123 4567', '639171234567', '63-917-1234567', '(0917) 123-4567', '0917.123.4567', '+639171234567', '09171234567']) {
      assert.equal(Q.normaliseMobile(m), '09171234567', m);
    }
  });
  it('rejects a landline, a short number, letters and the wrong prefix', () => {
    for (const m of ['0817 123 4567', '0917123456', '091712345678', '02 8123 4567', '+1 917 123 4567', '9171234567', 'call me', '', null, undefined, 9171234567]) {
      assert.equal(Q.normaliseMobile(m), null, String(m));
      assert.equal(Q.validateContact({ ...good(), mobile: m }).ok, false, String(m));
    }
  });
  it('name 2..120, e-mail shape and <= 160, company optional <= 120 (blank -> "")', () => {
    assert.equal(Q.validateContact({ ...good(), name: 'J' }).ok, false);
    assert.equal(Q.validateContact({ ...good(), name: 'x'.repeat(121) }).ok, false);
    for (const e of ['nope', 'a@b', '@x.com', 'a b@c.com', 'a@@c.com', `${'x'.repeat(155)}@e.com`]) assert.equal(Q.validateContact({ ...good(), email: e }).ok, false, e);
    assert.equal(Q.validateContact({ ...good(), email: ' Juan@Example.COM ' }).clean.email, 'Juan@Example.COM');     // stored as typed, trimmed
    assert.equal(Q.validateContact({ ...good(), company: undefined }).clean.company, '');
    assert.equal(Q.validateContact({ ...good(), company: 'x'.repeat(121) }).ok, false);
    assert.equal(Q.validateContact({ ...good(), company: 5 }).ok, false);
  });
  it('an unknown key is an error', () => {
    assert.ok(Q.validateContact({ ...good(), role: 'admin' }).errors.some((e) => e.indexOf('Unknown field') === 0));
  });
});

describe('normaliseProductDoc — the Quote Builder loadDatabase() mapping', () => {
  it('reads the current fields', () => {
    const p = Q.normaliseProductDoc('A-1', { title: 'T', category: 'c', unit: 'set', basePrice: 10, formulaType: 'per_run', measurement: { W: 5 }, formula: { pricePerRun: 2 }, specs: [{ label: 'x', options: ['a'] }] });
    assert.deepEqual(p, { id: 'A-1', category: 'c', name: 'T', formulaType: 'per_run', basePrice: 10, defaultDimensions: { W: 5 }, formula: { pricePerRun: 2 }, specs: [{ label: 'x', options: ['a'] }], unit: 'set' });
  });
  it('falls back for the legacy placeholder schema: name, baseRate, defaultDimensions, fixed, pc', () => {
    const p = Q.normaliseProductDoc('L-1', { name: 'Legacy', baseRate: 99, defaultDimensions: { W: 7 } });
    assert.equal(p.name, 'Legacy');
    assert.equal(p.basePrice, 99);
    assert.deepEqual(p.defaultDimensions, { W: 7 });
    assert.equal(p.formulaType, 'fixed');
    assert.equal(p.unit, 'pc');
    assert.deepEqual(p.formula, {});
    assert.deepEqual(p.specs, []);
  });
  it('a 0 basePrice is kept (?? not ||), a missing one becomes 0, a non-array specs becomes []', () => {
    assert.equal(Q.normaliseProductDoc('Z', { basePrice: 0, baseRate: 5 }).basePrice, 0);
    assert.equal(Q.normaliseProductDoc('Z', {}).basePrice, 0);
    assert.deepEqual(Q.normaliseProductDoc('Z', { specs: 'nope' }).specs, []);
    assert.equal(Q.normaliseProductDoc('Z', null).name, '');
  });
  it('never carries a cost field (the products doc has none, and nothing else is copied)', () => {
    const p = Q.normaliseProductDoc('C', { title: 'x', capitalMaterials: 1, capitalLabor: 2, bom: [1], laborHours: { a: 1 }, leadTime: '3d' });
    assert.deepEqual(Object.keys(p).sort(), ['basePrice', 'category', 'defaultDimensions', 'formula', 'formulaType', 'id', 'name', 'specs', 'unit']);
  });
});

describe('ONLY PUBLISHED PRODUCTS ARE QUOTABLE — the allowlist is generated, not hand-kept', () => {
  const ALLOW = JSON.parse(read('functions/qr-published.json'));
  const pubJson = JSON.parse(read('scripts/public-categories.json'));
  const cat = read('catalogue/index.html');
  const islandMatch = cat.match(/<script type="application\/json" id="qr-catalogue">([\s\S]*?)<\/script>/);
  const island = islandMatch ? JSON.parse(islandMatch[1]) : null;
  const cardIds = [...cat.matchAll(/<li class="cat-card[^"]*" data-id="([^"]+)"/g)].map((m) => m[1]);
  const published = Q.publishedIds();

  it('functions/qr-published.json is well-formed: sorted, unique, safe ids, count matches, no price anywhere', () => {
    assert.ok(Array.isArray(ALLOW.ids) && ALLOW.ids.length === 14, 'the 14 fixed items (64 SKUs are absorbed by the eleven families)');
    assert.deepEqual([...ALLOW.ids], ['BA-006', 'BA-011', 'CE-011', 'CE-024', 'CE-030', 'CE-031', 'MS-015', 'MS-016', 'RF-001', 'RF-002', 'RF-003', 'RF-004', 'RF-005', 'RF-006'], 'exactly these: the fryers, griddles, grillers and deck ovens are configurable now');
    assert.equal(ALLOW.count, ALLOW.ids.length);
    assert.deepEqual([...ALLOW.ids], [...ALLOW.ids].sort());
    assert.equal(new Set(ALLOW.ids).size, ALLOW.ids.length);
    for (const id of ALLOW.ids) assert.match(id, /^[A-Za-z0-9_-]+$/);
    assert.deepEqual(Object.keys(ALLOW).sort(), ['_readme', 'count', 'ids']);
    assert.ok(!/basePrice|priceAdder|₱|\bPHP\b|formula/.test(JSON.stringify(ALLOW).replace(ALLOW._readme, '')));
  });

  it('is exactly the FIXED products on the committed /catalogue/ page (the cards, the data island, the allowlist agree), and with the SKUs the families absorb it is every published product', () => {
    assert.ok(island, 'the data island is missing from catalogue/index.html — run: node scripts/build-catalogue.js');
    const a = [...ALLOW.ids].sort();
    assert.deepEqual([...island.products.map((p) => p.id)].sort(), a, 'island vs allowlist');
    assert.deepEqual([...cardIds].sort(), a, 'card data-id vs allowlist');
    const absorbed = Object.values(FAMS.families).flatMap((f) => Object.keys(f.absorbed));
    assert.deepEqual([...a, ...absorbed].sort(), Object.keys(pubJson.products).sort(), 'fixed + absorbed vs public-categories.json');
    assert.ok(!absorbed.some((id) => published.has(id)), 'an absorbed SKU is still quotable as a plain line');
    assert.equal(published.size, a.length);
  });

  it('contains NOTHING from the excluded categories (EX- exhaust · FA- fresh air · GL- gas line · FS- fire suppression) or the excluded items — the 7 hoods are configurable (never plain lines), the other 20 exhaust products are excluded by id', () => {
    for (const id of ALLOW.ids) assert.ok(!/^(EX|FA|GL|FS)-/.test(id), `${id} is from an excluded category`);
    for (const id of Object.keys(pubJson.excludedProducts)) assert.ok(!published.has(id), `${id} is an excluded item but is quotable`);
    assert.equal(Object.keys(pubJson.excludedProducts).length, 68, 'the 21 non-equipment items + the 27 specialised items of Preparation, Washing and Storage (owner ruling (b)) + the 20 exhaust products that are not hoods (2026-10-28)');
    const excludedExhaust = Object.keys(pubJson.excludedProducts).filter((id) => id.startsWith('EX-'));
    assert.equal(excludedExhaust.length, 20);
    const hoods = Object.keys(pubJson.products).filter((id) => id.startsWith('EX-'));
    assert.deepEqual(hoods.sort(), ['EX-001', 'EX-002', 'EX-003', 'EX-018', 'EX-019', 'EX-020', 'EX-021']);
    for (const id of hoods) assert.ok(!published.has(id), `${id} (a hood) must not be quotable as a plain line`);
    assert.deepEqual(Object.keys(FAMS.families.hood.absorbed), hoods, 'the 7 hoods are exactly what the hood family absorbs');
  });

  it('the server drops every unpublished product doc, then refuses its id with the SAME message an unknown id gets', () => {
    // a Firestore master that holds EVERYTHING: the published products, the 21 excluded items, family samples, a legacy placeholder, a new unmapped product
    const everything = [
      ...ALLOW.ids.map((id) => prodDoc(id, { title: `Pub ${id}`, basePrice: 1000, formulaType: 'fixed', measurement: {}, specs: [] })),
      ...Object.keys(pubJson.excludedProducts).map((id) => prodDoc(id, { title: `Excluded ${id}`, basePrice: 1000, formulaType: 'fixed' })),     // (the 20 non-hood exhaust products among them)
      ...['EX-001', 'EX-017', 'FA-001', 'FA-009', 'GL-001', 'GL-003', 'FS-001', 'FS-006', 'MS-099', 'NEW-001', 'ZZ-000'].map((id) => prodDoc(id, { title: `Other ${id}`, basePrice: 1000, formulaType: 'fixed' })),
      prodDoc('legacy-doc-1', { name: 'Steel Fabrication', baseRate: 5000, code: 'X' }),
    ];
    const idx = Q.buildProductIndex(everything);                               // the REAL allowlist
    assert.equal(idx.size, ALLOW.ids.length);
    const unknownMsg = Q.normaliseItems([item('NOT-A-PRODUCT')], idx).errors[0];
    assert.equal(unknownMsg, Q.GONE_MSG);
    // the SKUs a family absorbed are no longer plain lines either: they get the same refusal (a stale page / a saved line is converted by the page, never accepted here)
    const absorbedIds = Object.values(FAMS.families).flatMap((f) => Object.keys(f.absorbed));
    absorbedIds.forEach((id) => everything.push(prodDoc(id, { title: `Absorbed ${id}`, basePrice: 1000, formulaType: 'fixed' })));
    const idx2 = Q.buildProductIndex(everything);
    assert.equal(idx2.size, ALLOW.ids.length, 'an absorbed SKU leaked into the plain-line index');
    const mustRefuse = [...Object.keys(pubJson.excludedProducts), ...absorbedIds, 'EX-001', 'EX-017', 'FA-001', 'FA-009', 'GL-001', 'GL-003', 'FS-001', 'FS-006', 'MS-099', 'NEW-001', 'ZZ-000', 'legacy-doc-1'];
    for (const id of mustRefuse) {
      const r = Q.normaliseItems([item(id)], idx);
      assert.equal(r.ok, false, `${id} must be refused`);
      assert.deepEqual(r.errors, [unknownMsg], `${id} must get the same refusal as an unknown id`);
      assert.deepEqual(r.badIds, [id]);
    }
    for (const id of ALLOW.ids) assert.equal(Q.normaliseItems([item(id)], idx).ok, true, `${id} must be quotable`);
  });

  it('a malformed allowlist FILE publishes NOTHING: not an object, no ids, a non-string or unsafe id, a duplicate-free safe list passes', () => {
    for (const bad of [null, undefined, 'x', 5, [], {}, { ids: [] }, { ids: 'CE-001' }, { ids: ['CE-001', 7] }, { ids: ['CE-001', 'bad id'] }, { ids: ['CE-001', '../x'] }, { ids: ['CE-001', ''] }]) {
      assert.equal(Q.publishedIds(bad).size, 0, JSON.stringify(bad));
    }
    assert.deepEqual([...Q.publishedIds({ ids: ['CE-001', 'PW_2-b'] })].sort(), ['CE-001', 'PW_2-b']);
    assert.equal(Q.publishedIds().size, ALLOW.ids.length);                    // no argument -> the committed file
  });

  it('a broken or empty allowlist publishes NOTHING (fail closed)', () => {
    const idx = Q.buildProductIndex(DOCS, new Set());
    assert.equal(idx.size, 0);
    assert.equal(Q.normaliseItems([item('S-FIX')], idx).ok, false);
    assert.equal(Q.buildProductIndex(DOCS, new Set(['S-FIX'])).size, 1);
  });

  it('(local only) is exactly what the build derives from the private master — and every master product in an excluded category is refused', {
    skip: (() => { try { return resolveMaster() ? false : 'the private master (products-database.json) is not present'; } catch (_) { return 'no master'; } })(),
  }, () => {
    const master = JSON.parse(B.stripJsonComments(fs.readFileSync(resolveMaster(), 'utf8').replace(/^﻿/, '')));
    const pub = B.loadPublicCategories({ ids: master.products.map((p) => p.id) });
    const fromBuild = B.publishedProductIds(master, pub);
    const absorbedNow = new Set(Object.values(FAMS.families).flatMap((f) => Object.keys(f.absorbed)));
    assert.deepEqual([...ALLOW.ids].sort(), [...fromBuild].filter((id) => !absorbedNow.has(id)).sort(), 'functions/qr-published.json is stale — run: node scripts/build-catalogue.js');
    for (const p of master.products) {
      if (B.EXCLUDED_CATEGORIES.includes(p.category)) assert.ok(!published.has(p.id), `${p.id} (${p.category}) is quotable`);
    }
    assert.equal(master.products.filter((p) => B.EXCLUDED_CATEGORIES.includes(p.category)).length, 19, '46 before the exhaust category was un-excluded, minus its 27 products');
    // the exhaust category (2026-10-28): every one of its 27 products is decided — a hood (configurable, never a plain line) or excluded by id — and none is quotable
    const exhaust = master.products.filter((p) => p.category === 'exhaust_system');
    assert.equal(exhaust.length, 27);
    assert.equal(exhaust.filter((p) => absorbedNow.has(p.id)).length, 7);
    assert.equal(exhaust.filter((p) => Object.prototype.hasOwnProperty.call(pub.excludedProducts, p.id)).length, 20);
    for (const p of exhaust) assert.ok(!published.has(p.id), `${p.id} (exhaust) is quotable as a plain line`);
  });

  it('the data island is price-free by construction: only id / name / cat / unit / dims / specs, no price token', () => {
    assert.ok(island);
    for (const p of island.products) {
      for (const k of Object.keys(p)) assert.ok(['id', 'name', 'cat', 'unit', 'dims', 'specs'].includes(k), `unexpected island key ${k}`);
      assert.ok(['preparation', 'washing', 'cooking', 'ventilation', 'storage', 'refrigeration'].includes(p.cat), `${p.id} cat ${p.cat}`);
      for (const s of p.specs || []) {
        assert.deepEqual(Object.keys(s).filter((k) => !['label', 'options', 'default'].includes(k)), []);
        if (s.default !== undefined) assert.ok(s.options.includes(s.default));
      }
    }
    const raw = islandMatch[1];
    assert.ok(!B.MONEY_RE.test(raw) && !B.FORMULA_RE.test(raw), 'a price token is in the island');
    assert.ok(!/basePrice|priceAdder|formulaType|laborHours|leadTime|rateW100|pricePer/.test(raw));
  });
});

describe('normaliseItems — spec §4.3 items row', () => {
  const n = (items) => Q.normaliseItems(items, byId);
  it('a valid line is re-derived from the master: name, cat and unit are the master\'s, never the client\'s', () => {
    const r = n([{ id: 'S-LEN', qty: 2, size: null, runs: null, specs: [], note: ' hello ' }]);
    assert.equal(r.ok, true, r.errors.join('|'));
    assert.deepEqual(r.items[0], {
      n: 1, id: 'S-LEN', name: 'Synthetic Stove', cat: 'cooking_line', unit: 'pc', qty: 2, runs: null,
      size: { W: 1200, D: 600, H: 800 }, sizeCustom: false,
      specs: [{ label: 'Basin Depth', value: '300mm' }, { label: 'Faucet', value: 'Single' }], note: 'hello',
    });
  });
  it('a stored name / cat / unit / price the client sends is refused as an unknown key, not trusted', () => {
    for (const k of ['name', 'cat', 'unit', 'unitPrice', 'price', 'amount', 'basePrice', 'uid', 'formulaType']) {
      const r = n([{ id: 'S-FIX', qty: 1, [k]: 'x' }]);
      assert.equal(r.ok, false, k);
    }
  });
  it('a plain line carrying family / config / dims is REFUSED as an unknown key, and a family line without the family machinery is refused (never ignored)', () => {
    for (const k of ['family', 'config', 'dims', 'familyId2']) {
      const r = n([{ id: 'S-FIX', qty: 1, [k]: {} }]);
      assert.equal(r.ok, false, k);
      assert.match(r.errors[0], /unknown field/);
    }
    // a family line, but the caller supplied no families: the same refusal an unknown product gets
    const f = n([{ familyId: 'sink', config: {}, dims: {}, qty: 1 }]);
    assert.equal(f.ok, false);
    assert.deepEqual(f.errors, [Q.GONE_MSG]);
    // id AND familyId together: the id is an unknown key of a family line
    assert.equal(Q.normaliseItems([{ id: 'S-FIX', familyId: 'sink', config: {}, qty: 1 }], byId, { families: FAMS, primaries: new Map() }).ok, false);
  });
  it('a CONFIGURED line carries exactly { familyId, config, dims, qty, note }: any other field — a price, a total, an id, a name, a size, a kind — is refused as an unknown key', () => {
    const primaries = new Map(FAMS.order.map((f) => [f, { id: FAMS.families[f].primary }]));
    const ok = { familyId: 'sink', config: {}, dims: {}, qty: 1 };
    assert.equal(Q.normaliseItems([ok], byId, { families: FAMS, primaries }).ok, true);
    assert.equal(Q.normaliseItems([{ ...ok, note: 'near the door' }], byId, { families: FAMS, primaries }).ok, true);
    for (const k of ['price', 'unitPrice', 'amount', 'total', 'cost', 'rate', 'id', 'name', 'cat', 'unit', 'size', 'runs', 'specs', 'kind', 'uid', 'sizeCustom', 'priority', 'x']) {
      const r = Q.normaliseItems([{ ...ok, [k]: 1 }], byId, { families: FAMS, primaries });
      assert.equal(r.ok, false, k);
      assert.match(r.errors[0], new RegExp('unknown field "' + k + '"'), k);
    }
    // an own __proto__ key is not an allowed key either
    assert.equal(Q.normaliseItems([JSON.parse('{"familyId":"sink","config":{},"dims":{},"qty":1,"__proto__":{"price":1}}')], byId, { families: FAMS, primaries }).ok, false);
  });
  it('quantity must be a whole number 1..maxQtyPerLine', () => {
    for (const bad of [0, -1, 21, 999, 1.5, '2', null, undefined, NaN]) assert.equal(n([{ id: 'S-FIX', qty: bad }]).ok, false, String(bad));
    assert.equal(n([{ id: 'S-FIX', qty: 20 }]).ok, true);
  });
  it('1..maxItems lines: an empty list, a non-array and 41 lines are refused', () => {
    assert.equal(n([]).ok, false);
    assert.equal(n('x').ok, false);
    assert.equal(n(null).ok, false);
    assert.equal(n(Array.from({ length: LIMITS.maxItems + 1 }, () => item('S-FIX'))).ok, false);
    const spread = ['S-FIX', 'S-NOD', 'S-LEN', 'S-ZERO', 'S-CFG'];                           // 40 lines over 5 products: 8 units each, under the per-product cap
    assert.equal(n(Array.from({ length: LIMITS.maxItems }, (_, i) => item(spread[i % spread.length]))).ok, true);
    assert.equal(n(Array.from({ length: LIMITS.maxItems }, () => item('S-FIX'))).ok, false);   // ...but 40 lines of ONE product is 40 units
  });
  it('ONE PRODUCT, ONE MULTIPLIER: units of a product (qty x runs) are capped at maxQtyPerProduct across ALL of its lines — duplicates, other sizes, other notes', () => {
    const cap = LIMITS.maxQtyPerProduct;
    assert.equal(cap, 20);
    assert.equal(n([item('S-FIX', { qty: 10 }), item('S-FIX', { qty: 10 })]).ok, true);               // exactly 20 in two lines
    const over = n([item('S-FIX', { qty: 10 }), item('S-FIX', { qty: 11 })]);
    assert.equal(over.ok, false);
    assert.match(over.errors[0], /at most 20 of one product/);
    assert.match(over.errors[0], /your list has 21/);
    // a fixed-price product ignores size, so "different" lines are the same unit price: they still count together
    assert.equal(n([item('S-FIX', { qty: 20 }), item('S-FIX', { qty: 1, size: { W: 1000 } })]).ok, false);
    assert.equal(n([item('S-FIX', { qty: 20, note: 'a' }), item('S-FIX', { qty: 1, note: 'b' })]).ok, false);
    // 40 lines x qty 20 (the 800-unit lever) is refused outright
    assert.equal(n(Array.from({ length: 40 }, () => item('S-FIX', { qty: 20 }))).ok, false);
    // different products each get their own allowance
    assert.equal(n([item('S-FIX', { qty: 20 }), item('S-NOD', { qty: 20 }), item('S-LEN', { qty: 20 })]).ok, true);
    // runs multiply too: 20 runs is the ceiling for a run product, however it is split
    assert.equal(n([item('S-RUN', { runs: 20 })]).ok, true);
    assert.equal(n([item('S-RUN', { runs: 10 }), item('S-RUN', { runs: 10 })]).ok, true);
    assert.equal(n([item('S-RUN', { runs: 10 }), item('S-RUN', { runs: 11 })]).ok, false);
    assert.equal(n([item('S-RUN', { runs: 11, qty: 2 })]).ok, false);                                 // qty x runs = 22
    assert.equal(n([item('S-RUN', { runs: 10, qty: 2 })]).ok, true);                                  // = 20
  });
  it('PROPERTY: any basket normaliseItems accepts can multiply one product\'s unit price by at most 20 (the gate / rounding oracle has no lever arm)', () => {
    let seed = 0x2545F491;                                                                              // tiny deterministic PRNG, never Math.random
    const rnd = () => { seed ^= seed << 13; seed >>>= 0; seed ^= seed >>> 17; seed ^= seed << 5; seed >>>= 0; return seed / 4294967296; };
    const unit = Q.computeBasket(Q.normaliseItems([item('S-FIX')], byId).items, byId, {}, ESTIMATE).exact;            // one unit's list price
    let accepted = 0, refused = 0;
    for (let t = 0; t < 600; t++) {
      const lines = 1 + Math.floor(rnd() * 40);
      const items = Array.from({ length: lines }, () => item('S-FIX', { qty: 1 + Math.floor(rnd() * 20), size: rnd() < 0.5 ? { W: 100 + 10 * Math.floor(rnd() * 200) } : null, note: rnd() < 0.5 ? 'n' + Math.floor(rnd() * 9) : '' }));
      const r = n(items);
      if (!r.ok) { refused++; continue; }
      accepted++;
      const b = Q.computeBasket(r.items, byId, {}, ESTIMATE);
      assert.ok(b.exact <= unit * LIMITS.maxQtyPerProduct, `exact ${b.exact} exceeds 20 units (${unit * 20})`);
    }
    assert.ok(accepted > 20 && refused > 20, `the property sweep must exercise both outcomes (accepted ${accepted}, refused ${refused})`);
  });
  it('the note is text <= maxNote with control characters stripped', () => {
    assert.equal(n([{ id: 'S-FIX', qty: 1, note: 'x'.repeat(LIMITS.maxNote + 1) }]).ok, false);
    assert.equal(n([{ id: 'S-FIX', qty: 1, note: 'x'.repeat(LIMITS.maxNote) }]).ok, true);
    assert.equal(n([{ id: 'S-FIX', qty: 1, note: 7 }]).ok, false);
    assert.equal(n([{ id: 'S-FIX', qty: 1, note: 'a\u0000b\nc' }]).items[0].note, 'abc');
    assert.equal(n([{ id: 'S-FIX', qty: 1 }]).items[0].note, '');
  });
  it('size, runs and specs go through pricing-core.validateSelection: bounds, step, keys, runs only for per_run, specs by label/value', () => {
    assert.equal(n([item('S-FIX', { size: { W: 99999 } })]).ok, false);
    assert.equal(n([item('S-FIX', { size: { W: 1005 } })]).ok, false);
    assert.equal(n([item('S-FIX', { size: { W: 1000 } })]).items[0].sizeCustom, true);
    assert.equal(n([item('S-NOD', { size: { W: 500 } })]).ok, false);                       // no dims at all
    assert.equal(n([item('S-NOD')]).items[0].size, null);                                   // "standard size"
    assert.equal(n([item('S-RUN', { runs: 4 })]).items[0].runs, 4);
    assert.equal(n([item('S-RUN')]).ok, false);
    assert.equal(n([item('S-FIX', { runs: 2 })]).ok, false);
    assert.equal(n([item('S-LEN', { specs: [{ label: 'Faucet', value: 'Chrome' }] })]).ok, false);
    assert.equal(n([item('S-LEN', { specs: [{ label: 'Nope', value: 'x' }] })]).ok, false);
    assert.deepEqual(n([item('S-LEN', { specs: [{ label: 'Faucet', value: 'Gooseneck' }] })]).items[0].specs[1], { label: 'Faucet', value: 'Gooseneck' });
  });
  it('an unknown id collapses to ONE message and reports the ids so the page can remove those lines', () => {
    const r = n([item('S-FIX'), item('NOPE-1'), item('NOPE-2'), item('X-HIDDEN')]);
    assert.equal(r.ok, false);
    assert.deepEqual(r.errors, [Q.GONE_MSG]);
    assert.deepEqual(r.badIds, ['NOPE-1', 'NOPE-2', 'X-HIDDEN']);
  });
  it('line numbers follow the request order and rubbish entries are errors, never throws', () => {
    const r = n([item('S-FIX'), item('S-LEN'), item('S-NOD')]);
    assert.deepEqual(r.items.map((i) => i.n), [1, 2, 3]);
    for (const bad of [null, 5, 'x', [], [1]]) assert.equal(n([bad]).ok, false);
    assert.equal(n([{ id: ['S-FIX'], qty: 1 }]).ok, false);
    assert.equal(n([{ id: '__proto__', qty: 1 }]).ok, false);
    assert.equal(n([{ id: 'constructor', qty: 1 }]).ok, false);
  });
});

describe('isPlainJsonTree — the callable decoder\'s __proto__ quirk (payload-size and allowlist bypass)', () => {
  // firebase-functions decodes a request with bracket assignment, so {"__proto__":{…}} on the wire becomes an object with no own
  // keys whose fields live on its PROTOTYPE. Emulated here with the same assignment.
  const smuggle = (inner, rest) => { const o = Object.assign({}, rest || {}); o['__proto__'] = inner; return o; };
  it('accepts ordinary decoded JSON of every shape the page sends', () => {
    const ok = { sessionToken: 'x'.repeat(43), defVersion: 1, entityType: 'private', items: [{ id: 'S-FIX', qty: 2, size: { W: 1000 }, runs: null, specs: [{ label: 'a', value: 'b' }], note: '' }], honeypot: '', lastEstimate: null };
    assert.equal(Q.isPlainJsonTree(ok), true);
    for (const v of [null, undefined, 0, 'x', true, [], {}, [1, [2, [3]]]]) assert.equal(Q.isPlainJsonTree(v), true, String(v));
    assert.equal(Q.isPlainJsonTree(JSON.parse('{"__proto__":{"a":1}}')), true);                    // an OWN key named __proto__ is just an unknown key, rejected by the allowlists
  });
  it('REFUSES a smuggled prototype at the top level, nested in an item, inside an array and in a sub-object', () => {
    const inner = { defVersion: 1, entityType: 'private', items: [] };
    const top = smuggle(inner);
    assert.deepEqual(Object.keys(top), [], 'the smuggled object has no own keys');
    assert.equal(JSON.stringify(top), '{}', 'so JSON.stringify(data).length — the size guard — reads 2');
    assert.equal(top.defVersion, 1, 'yet its fields resolve through the prototype');
    assert.equal(Q.isPlainJsonTree(top), false);
    assert.equal(Q.isPlainJsonTree({ items: [smuggle({ qty: 3, family: 'sink' }, { id: 'S-FIX' })] }), false);
    assert.equal(Q.isPlainJsonTree({ a: { b: [{ c: smuggle({ d: 1 }) }] } }), false);
    assert.equal(Q.isPlainJsonTree(smuggle(null)), false);                                           // a null prototype is refused too (no hasOwnProperty)
  });
  it('refuses everything that is not plain data: class instances, Map/Date, accessors, symbols, holes, functions, bigints, null-prototype objects', () => {
    class Evil { constructor() { this.a = 1; } }
    const acc = {}; Object.defineProperty(acc, 'x', { enumerable: true, get() { return 1; } });
    const sym = { [Symbol('s')]: 1 };
    const holes = [1, , 3];                                                                          // eslint-disable-line no-sparse-arrays
    const nullProto = Object.create(null); nullProto.a = 1;
    for (const bad of [new Evil(), new Map(), new Date(), acc, sym, holes, () => 1, 10n, nullProto, Symbol('z'), Object.create({ a: 1 })]) {
      assert.equal(Q.isPlainJsonTree(bad), false, Object.prototype.toString.call(bad));
    }
  });
  it('is bounded: depth and node budgets (a hostile body cannot make validation expensive) and it never throws', () => {
    let deep = {}; let cur = deep; for (let i = 0; i < 12; i++) { cur.a = {}; cur = cur.a; }
    assert.equal(Q.isPlainJsonTree(deep), false);
    assert.equal(Q.isPlainJsonTree(Array.from({ length: 4001 }, () => 1)), false);
    assert.equal(Q.isPlainJsonTree(Array.from({ length: 3000 }, () => 1)), true);
    const throwing = new Proxy({}, { getPrototypeOf() { throw new Error('boom'); } });
    assert.doesNotThrow(() => Q.isPlainJsonTree(throwing));
    assert.equal(Q.isPlainJsonTree(throwing), false);
  });
  it('qr_abuse retention is 30 days (a best-effort purge in the callables)', () => {
    assert.equal(Q.ABUSE_TTL_MS, 30 * 24 * 3600e3);
  });
});

describe('computeBasket — the staff-only figures (spec §6)', () => {
  const norm = (items) => Q.normaliseItems(items, byId).items;
  const basket = (items, constants) => Q.computeBasket(norm(items), byId, constants || {}, ESTIMATE);

  it('sums unit price x qty over PRICED lines; unpriced lines are excluded and counted for review (O6)', () => {
    const b = basket([item('S-FIX', { qty: 2 }), item('S-ZERO'), item('S-NOD', { qty: 3 })]);
    assert.equal(b.exact, 2 * 4217 + 3 * 1111);
    assert.equal(b.pricedCount, 2);
    assert.equal(b.reviewCount, 1);
    assert.equal(b.distinctPriced, 2);
    assert.deepEqual(b.lines.map((l) => [l.id, l.unitPrice, l.lineTotal, l.priced]), [['S-FIX', 4217, 8434, true], ['S-ZERO', 0, 0, false], ['S-NOD', 1111, 3333, true]]);
  });
  it('two lines of the SAME product are one distinct product', () => {
    const b = basket([item('S-FIX'), item('S-FIX', { size: { W: 1000 } })]);
    assert.equal(b.pricedCount, 2);
    assert.equal(b.distinctPriced, 1);
  });
  it('prices per formulaType through pricing-core: per_length surcharge, per_run x runs, per_area, fixed ignores size', () => {
    assert.equal(basket([item('S-LEN', { size: { W: 1500 } })]).lines[0].unitPrice, Math.round(7770 + 300 * 3.3));
    assert.equal(basket([item('S-LEN', { size: { D: 900 } })]).lines[0].unitPrice, Math.round(7770 + (300 / 100) * 31));
    assert.equal(basket([item('S-RUN', { runs: 4 })]).lines[0].unitPrice, 903 * 4);
    assert.equal(basket([item('S-AREA', { size: { W: 2000, H: 1500 } })]).lines[0].unitPrice, Math.round(3 * 611));
    assert.equal(basket([item('S-FIX', { size: { W: 1500 } })]).lines[0].unitPrice, 4217);
    assert.equal(basket([item('S-CFG')]).lines[0].unitPrice, 2999);
  });
  it('spec adders and the material-price-index multiplier apply in the builder\'s order (multiplier first, adders after)', () => {
    const pick = (a, b) => ({ specs: [{ label: 'Basin Depth', value: a }, { label: 'Faucet', value: b }] });
    assert.equal(basket([item('S-LEN', pick('350mm', 'Gooseneck'))]).lines[0].unitPrice, 7770 + 150 + 60);
    assert.equal(basket([item('S-LEN', pick('350mm', 'Gooseneck'))], { materialPriceIndexMultiplier: 1.1 }).lines[0].unitPrice, Math.round(7770 * 1.1 + 150 + 60));
  });
  it('customSizeCount counts the lines whose size differs from the default; sizeAdjusted is per line', () => {
    const b = basket([item('S-FIX', { size: { W: 1000 } }), item('S-FIX'), item('S-LEN', { size: { H: 900 } })]);
    assert.equal(b.customSizeCount, 2);
    assert.deepEqual(b.lines.map((l) => l.sizeAdjusted), [true, false, true]);
  });
  it('a missing D / H rate surfaces as a per-line warning', () => {
    const noRate = Q.buildProductIndex([prodDoc('S-LEN', { title: 'N', basePrice: 1000, formulaType: 'per_length', measurement: { W: 1200, D: 600 }, formula: { baseLengthMm: 1200, pricePerExtraMm: 1 } })], new Set(['S-LEN']));
    const items = Q.normaliseItems([item('S-LEN', { size: { D: 900 } })], noRate).items;
    const b = Q.computeBasket(items, noRate, {}, ESTIMATE);
    assert.match(b.lines[0].warnings[0], /No rate on file for custom Width/);
    assert.equal(b.lines[0].unitPrice, 1000);
  });
  it('carries the basket hash', () => {
    const items = norm([item('S-FIX')]);
    assert.equal(Q.computeBasket(items, byId, {}, ESTIMATE).basketHash, Q.basketHash(items));
  });
});

describe('basketHash — canonical, order-independent, qty- and size-sensitive, note-blind', () => {
  const norm = (items) => Q.normaliseItems(items, byId).items;
  const h = (items) => Q.basketHash(norm(items));
  it('is a sha256 hex string', () => assert.match(h([item('S-FIX')]), /^[0-9a-f]{64}$/));
  it('does not depend on line order, nor on how an unchanged default is spelled', () => {
    assert.equal(h([item('S-FIX'), item('S-NOD')]), h([item('S-NOD'), item('S-FIX')]));
    assert.equal(h([item('S-FIX')]), h([item('S-FIX', { size: { W: 900, D: 700, H: 850 } })]));
    assert.equal(h([item('S-LEN')]), h([item('S-LEN', { specs: [{ label: 'Faucet', value: 'Single' }] })]));
    assert.equal(h([item('S-LEN', { specs: [{ label: 'Faucet', value: 'Gooseneck' }, { label: 'Basin Depth', value: '350mm' }] })]), h([item('S-LEN', { specs: [{ label: 'Basin Depth', value: '350mm' }, { label: 'Faucet', value: 'Gooseneck' }] })]));
  });
  it('changes with qty, size, runs and a spec choice — and NOT with the note', () => {
    const base = h([item('S-FIX')]);
    assert.notEqual(base, h([item('S-FIX', { qty: 2 })]));
    assert.notEqual(base, h([item('S-FIX', { size: { W: 1000 } })]));
    assert.notEqual(h([item('S-RUN', { runs: 2 })]), h([item('S-RUN', { runs: 3 })]));
    assert.notEqual(h([item('S-LEN')]), h([item('S-LEN', { specs: [{ label: 'Faucet', value: 'Gooseneck' }] })]));
    assert.equal(base, h([item('S-FIX', { note: 'a different note' })]));
  });
  it('two lines are not the same as one line with double the quantity', () => {
    assert.notEqual(h([item('S-FIX'), item('S-FIX')]), h([item('S-FIX', { qty: 2 })]));
  });
  it('a CONFIGURED line: the configuration, the size and the quantity change it; key order and the note do not; a configured line never equals a plain one', () => {
    const primaries = new Map(FAMS.order.map((f) => [f, { id: FAMS.families[f].primary }]));
    const hf = (lines) => { const r = Q.normaliseItems(lines, byId, { families: FAMS, primaries }); assert.equal(r.ok, true, (r.errors || []).join(' ')); return Q.basketHash(r.items); };
    const sink = (config, dims, qty, note) => ({ familyId: 'sink', config, dims, qty: qty || 1, note: note || '' });
    const A = sink({ basins: 2, faucet: 'prerinse' }, { W: 1000, D: 500, H: 850 });
    const base = hf([A]);
    assert.match(base, /^[0-9a-f]{64}$/);
    assert.equal(base, hf([sink({ faucet: 'prerinse', basins: 2 }, { H: 850, D: 500, W: 1000 })]), 'key order does not matter');
    assert.equal(base, hf([{ ...A, note: 'near the door' }]), 'the note is not part of the basket');
    assert.notEqual(base, hf([sink({ basins: 2, faucet: 'gooseneck' }, { W: 1000, D: 500, H: 850 })]), 'a different faucet');
    assert.notEqual(base, hf([sink({ basins: 2, faucet: 'prerinse', undershelf: true }, { W: 1000, D: 500, H: 850 })]), 'another option');
    assert.notEqual(base, hf([sink({ basins: 2, faucet: 'prerinse' }, { W: 1100, D: 500, H: 850 })]), 'a different size');
    assert.notEqual(base, hf([{ ...A, qty: 2 }]), 'a different quantity');
    assert.notEqual(base, hf([A, A]), 'two lines are not one line');
    assert.notEqual(base, h([item('S-FIX')]), 'a configured line never equals a plain one');
  });
});

describe('rangeFor / gateFor — R2 and O3 wired to the ruled config', () => {
  it('rangeFor uses the ruled factors and steps (VAT-exclusive by default)', () => {
    assert.deepEqual(Q.rangeFor(84120, ESTIMATE), { low: 75000, high: 100000, step: 5000 });
    assert.deepEqual(Q.rangeFor(500000, ESTIMATE), { low: 450000, high: 580000, step: 10000 });
  });
  it('O1 switch: vatBasis "inclusive" ranges exact x 1.12', () => {
    const r = Q.rangeFor(100000, { ...ESTIMATE, vatBasis: 'inclusive' });
    assert.deepEqual(r, { low: 100000, high: 130000, step: 5000 });        // 112,000 x 0.9 = 100,800 -> 100,000; x 1.15 = 128,800 -> 130,000 (the step follows the ranged figure)
    assert.deepEqual(Q.rangeFor(100000, ESTIMATE), { low: 90000, high: 115000, step: 5000 });
  });
  it('gateFor: >= 2 distinct priced OR exact >= 50,000, judged on the ex-VAT list total', () => {
    assert.equal(Q.gateFor({ distinctPriced: 1, exact: 49999 }, ESTIMATE).shown, false);
    assert.equal(Q.gateFor({ distinctPriced: 1, exact: 50000 }, ESTIMATE).shown, true);
    assert.equal(Q.gateFor({ distinctPriced: 2, exact: 1 }, ESTIMATE).shown, true);
    assert.equal(Q.gateFor({ distinctPriced: 1, exact: 49999 }, { ...ESTIMATE, vatBasis: 'inclusive' }).shown, false);
  });
});

describe('publicEstimate — THE response (no price ever)', () => {
  const norm = (items) => Q.normaliseItems(items, byId).items;
  const mk = (items, entity, over) => {
    const b = Q.computeBasket(norm(items), byId, {}, ESTIMATE);
    const gate = Q.gateFor(b, ESTIMATE);
    return { b, resp: Q.publicEstimate(b, Q.rangeFor(b.exact, ESTIMATE), gate, { ...ESTIMATE, ...(over || {}) }, entity || 'private', NOW) };
  };
  const KEYS = ['basketHash', 'currency', 'customSizeCount', 'deliveryIncluded', 'estimateVersion', 'high', 'low', 'notes', 'ok', 'pricedCount', 'reason', 'reviewCount', 'serverNow', 'shown', 'step', 'vatBasis'];

  it('has EXACTLY the spec §5.3 key set — shown, gated and disabled alike', () => {
    const shown = mk([item('S-LEN'), item('S-FIX')]).resp;
    const gated = mk([item('S-NOD')]).resp;
    const disabled = Q.publicEstimate(null, null, { shown: false, reason: 'disabled' }, ESTIMATE, 'private', NOW);
    for (const r of [shown, gated, disabled]) assert.deepEqual(Object.keys(r).sort(), KEYS);
  });
  it('shown: low / high / step are the rounded range; reason null; the fixed fields', () => {
    const { resp } = mk([item('S-LEN'), item('S-FIX')]);                                  // 7770 + 4217 = 11,987
    assert.equal(resp.shown, true);
    assert.equal(resp.reason, null);
    assert.deepEqual([resp.low, resp.high, resp.step], [10000, 15000, 5000]);             // 0.9 x 11,987 = 10,788 -> 10,000 ; 1.15 x = 13,785 -> 15,000
    assert.equal(resp.currency, 'PHP');
    assert.equal(resp.vatBasis, 'exclusive');
    assert.equal(resp.deliveryIncluded, false);
    assert.equal(resp.estimateVersion, ESTIMATE.version);
    assert.equal(resp.serverNow, new Date(NOW).toISOString());
    assert.equal(resp.ok, true);
    assert.match(resp.basketHash, /^[0-9a-f]{64}$/);
  });
  it('NOT shown (gate): low / high / step are null and reason is "gate"; counts still tell the page what is in the basket', () => {
    const { resp } = mk([item('S-NOD'), item('S-ZERO')]);
    assert.equal(resp.shown, false);
    assert.equal(resp.reason, 'gate');
    assert.deepEqual([resp.low, resp.high, resp.step], [null, null, null]);
    assert.equal(resp.pricedCount, 1);
    assert.equal(resp.reviewCount, 1);
  });
  it('disabled (O7): shown false, reason "disabled", everything numeric null / zero, no hash', () => {
    const r = Q.publicEstimate(null, null, { shown: false, reason: 'disabled' }, ESTIMATE, 'private', NOW);
    assert.equal(r.shown, false);
    assert.equal(r.reason, 'disabled');
    assert.deepEqual([r.low, r.high, r.step], [null, null, null]);
    assert.deepEqual([r.pricedCount, r.reviewCount, r.customSizeCount], [0, 0, 0]);
    assert.equal(r.basketHash, null);
  });
  it('never carries the exact total, a line, a unit price or ANY number equal to one (synthetic prices avoid a coincidence)', () => {
    const { b, resp } = mk([item('S-LEN', { qty: 3 }), item('S-FIX', { qty: 2, size: { W: 1000 } }), item('S-NOD')]);
    const json = JSON.stringify(resp);
    assert.ok(!/"exact|"lines"|unitPrice|lineTotal|basePrice|exactTotal|priceAdder|formula/.test(json), json);
    const nums = new Set();
    JSON.stringify(resp, (k, v) => { if (typeof v === 'number') nums.add(v); return v; });
    assert.ok(!nums.has(b.exact), 'the response contains the exact total');
    for (const l of b.lines) { assert.ok(!nums.has(l.unitPrice), `unit price ${l.unitPrice} leaked`); assert.ok(!nums.has(l.lineTotal), `line total ${l.lineTotal} leaked`); }
    for (const v of Object.values(resp)) assert.ok(typeof v !== 'object' || v === null || Array.isArray(v), 'a nested object in the response');
    assert.ok(resp.notes.every((x) => typeof x === 'string'));
  });
  it('notes come from QR_DEF.COPY: the VAT line and the delivery line always, the rest only when they apply', () => {
    const base = mk([item('S-LEN'), item('S-FIX')]).resp.notes;
    assert.deepEqual(base, [COPY.vatExclusive, COPY.deliveryExcluded]);
    assert.deepEqual(mk([item('S-LEN'), item('S-FIX')], 'private', { vatBasis: 'inclusive' }).resp.notes, [COPY.vatInclusive, COPY.deliveryExcluded]);
    assert.deepEqual(mk([item('S-LEN'), item('S-FIX')], 'private', { deliveryIncluded: true }).resp.notes, [COPY.vatExclusive]);
    assert.deepEqual(mk([item('S-LEN'), item('S-FIX', { size: { W: 1000 } })]).resp.notes, [COPY.vatExclusive, COPY.deliveryExcluded, COPY.customSizeNote]);
    assert.deepEqual(mk([item('S-LEN'), item('S-FIX'), item('S-ZERO')]).resp.notes, [COPY.vatExclusive, COPY.deliveryExcluded, COPY.reviewCount(1)]);
    assert.equal(COPY.reviewCount(1), '1 item priced after review.');
    assert.equal(COPY.reviewCount(3), '3 items priced after review.');
  });
  it('R7: the government procurement note is present IFF the entity is government (the range itself is unchanged)', () => {
    const priv = mk([item('S-LEN'), item('S-FIX')], 'private').resp;
    const gov = mk([item('S-LEN'), item('S-FIX')], 'government').resp;
    assert.ok(!priv.notes.includes(COPY.governmentNote));
    assert.ok(gov.notes.includes(COPY.governmentNote));
    assert.deepEqual([gov.low, gov.high, gov.step], [priv.low, priv.high, priv.step]);
    assert.ok(Q.publicEstimate(null, null, { shown: false, reason: 'disabled' }, ESTIMATE, 'government', NOW).notes.includes(COPY.governmentNote));
  });
  it('O1 / O2 flags are honoured from the config', () => {
    const r = mk([item('S-LEN'), item('S-FIX')], 'private', { vatBasis: 'inclusive', deliveryIncluded: true }).resp;
    assert.equal(r.vatBasis, 'inclusive');
    assert.equal(r.deliveryIncluded, true);
  });
});

// ── STANDARD CONSTRUCTION on the server (owner ruling 2026-10-28, QUOTE-BUILDER-CONFIGURATOR-SPEC §14.4 / §14.7): made-to-order tables, sinks and stoves have a 1.5 mm (16 ga) top plate as the STANDARD; the
// 1.2 mm top is a STAFF-ONLY option. qrEstimate / qrSubmit validate every configured line with ProductFamilies.validateLine WITHOUT options, so a visitor can never choose it; the stored line is the
// standard one with its construction sentence; the definitions moved to schema 2 (and to 3 with the five new families), so a sheet approved against an older schema prices nothing until
// it is approved again.
// (Mutation-tested in a scratch copy: the server passing { staff: true }; the family version left at 1 — each must fail here.)
describe('the staff-only top plate on the server: a visitor can never choose 1.2 mm, the stored line is the standard one with its construction, older-schema sheets are "priced after review"', () => {
  const PF = require('../functions/product-families.js');
  const WITH_TOP = ['prep_table', 'sink', 'dish_table', 'stove', 'wok_range'];
  const WITHOUT_TOP = FAMS.order.filter((f) => !WITH_TOP.includes(f));
  const primaries = new Map(FAMS.order.map((f) => [f, { id: FAMS.families[f].primary }]));
  const norm = (fid, config, dims) => Q.normaliseItems([{ familyId: fid, config, dims: dims || {}, qty: 1 }], byId, { families: FAMS, primaries });
  const staffMsg = (fid) => `"${FAMS.families[fid].label}": "Top plate" is chosen by our staff when the quotation is prepared.`;

  it('a 1.2 mm top is REFUSED with the staff message — for table, sink, dish table, stove and wok range, alone or with other options; any other non-standard value gets the same message', () => {
    for (const fid of WITH_TOP) {
      const dflt = PF.defaultConfig(FAMS.families[fid]);
      for (const config of [{ top: 1.2 }, { ...dflt, top: 1.2 }]) {
        const r = norm(fid, config);
        assert.equal(r.ok, false, fid);
        assert.deepEqual(r.errors, [staffMsg(fid)], fid);
        assert.deepEqual(r.items, [], 'nothing is stored for a refused line');
      }
      for (const v of [9, '1.2', '1.5', null, true, 0, [1.2]]) assert.deepEqual(norm(fid, { top: v }).errors, [staffMsg(fid)], `${fid} ${JSON.stringify(v)}`);
    }
    // the other families have no top plate to choose: it is an unknown option there
    for (const fid of WITHOUT_TOP) assert.match(norm(fid, { top: 1.2 }).errors[0], /"top" is not an option of this product/, fid);
  });

  const gradeMsg = (fid) => `"${FAMS.families[fid].label}": "Material" is chosen by our staff when the quotation is prepared.`;
  it('the steel grade is the same: SS316 is REFUSED with the staff message — on EVERY family, alone or with other options; any other non-standard value gets the same message; the standard grade, stated or absent, is accepted and stored as 304', () => {
    for (const fid of FAMS.order) {
      const dflt = PF.defaultConfig(FAMS.families[fid]);
      for (const config of [{ grade: 316 }, { ...dflt, grade: 316 }]) {
        const r = norm(fid, config);
        assert.equal(r.ok, false, fid);
        assert.deepEqual(r.errors, [gradeMsg(fid)], fid);
        assert.deepEqual(r.items, [], 'nothing is stored for a refused line');
      }
      for (const v of [9, '316', '304', null, true, 0, [316]]) assert.deepEqual(norm(fid, { grade: v }).errors, [gradeMsg(fid)], `${fid} ${JSON.stringify(v)}`);
      for (const config of [{}, { grade: 304 }]) {
        const r = norm(fid, config);
        assert.equal(r.ok, true, `${fid} ${JSON.stringify(config)}: ${(r.errors || []).join(' ')}`);
        assert.equal(r.items[0].config.grade, 304, `${fid}: stored config.grade`);
      }
      assert.equal(Q.basketHash(norm(fid, {}).items), Q.basketHash(norm(fid, { grade: 304 }).items), `${fid}: stating the standard grade changes nothing`);
    }
  });

  it('the standard 1.5 mm top, stated or absent, is accepted: the STORED configuration always carries top 1.5, and the same line hashes the same either way', () => {
    for (const fid of WITH_TOP) {
      for (const config of [{}, { top: 1.5 }]) {
        const r = norm(fid, config);
        assert.equal(r.ok, true, `${fid} ${JSON.stringify(config)}: ${(r.errors || []).join(' ')}`);
        assert.equal(r.items[0].config.top, 1.5, `${fid}: stored config.top`);
      }
      assert.equal(Q.basketHash(norm(fid, {}).items), Q.basketHash(norm(fid, { top: 1.5 }).items), `${fid}: stating the standard top changes nothing`);
    }
    for (const fid of WITHOUT_TOP) assert.ok(!('top' in norm(fid, {}).items[0].config), fid);
  });

  it('the stored specs end with the Construction row (the owner\'s sentence at the standard top) and never carry a "Top plate" row or the lighter top', () => {
    const SENTENCE = {
      prep_table: 'SS304 stainless steel · 1.5 mm (16 ga) top plate · 1.2 mm undershelves and upper shelves · square-tube posts with adjustable bullet feet',
      sink: 'SS304 stainless steel · 1.5 mm (16 ga) top plate · 1.2 mm undershelf, upper shelf and panels · square-tube posts with adjustable bullet feet',
      stove: 'SS304 stainless steel · 1.5 mm (16 ga) top plate · 1.2 mm body and panels · square-tube posts with adjustable bullet feet',
      cabinet: 'SS304 stainless steel · 1.2 mm body, doors and shelves · square-tube posts with adjustable bullet feet',
      wall_shelf: 'SS304 stainless steel · 1.2 mm shelves · fixed to the wall',
      rack: 'SS304 stainless steel · 1.2 mm shelves · square-tube frame · on wheels',
      dish_table: 'SS304 stainless steel · 1.5 mm (16 ga) top plate · 1.2 mm undershelf and splash · raised back and side splash, clean-dish landing · square-tube posts with adjustable bullet feet',
      wok_range: 'SS304 stainless steel · 1.5 mm (16 ga) top plate · 1.2 mm body and panels · recessed wok rings with high-pressure burners · square-tube posts with adjustable bullet feet',
      cooking_line: 'SS304 stainless steel · 1.2 mm body and panels · semi-non-stick griddle plate, gas-fired · square-tube stand with adjustable bullet feet',
      deck_oven: 'Insulated double-wall decks with a gas burner, gas valve and thermometer per deck · stainless steel outer body · set on your own base',
      hood: 'SS304 stainless steel · welded canopy with grease trough and oil cup · wall-mounted canopy · stainless baffle grease filters',
    };
    for (const fid of FAMS.order) {
      const it = norm(fid, {}).items[0];
      assert.deepEqual(it.specs.at(-1), { label: 'Construction', value: SENTENCE[fid] }, fid);
      assert.ok(!it.specs.some((s) => /top plate/i.test(s.label)), `${fid}: a "Top plate" row`);
      assert.ok(!/lighter|1\.2 mm top/.test(JSON.stringify(it.specs)), `${fid}: the lighter top in the stored specs`);
      // the Material row (the standard steel grade — a website line is always SS304) first, then one row per public option THAT APPLIES to the stored configuration (a conditional option that does not apply has none), then the Construction row
      assert.deepEqual(it.specs.map((s) => s.label), ['Material', ...PF.publicActiveGroups(FAMS.families[fid], it.config).map((g) => g.label), 'Construction'], fid);
      assert.deepEqual(it.specs[0], { label: 'Material', value: 'Stainless Steel 304 Food Grade' }, fid);
      assert.equal(it.config.grade, 304, `${fid}: the stored configuration states the standard steel grade`);
      assert.ok(!/316|laboratory/i.test(JSON.stringify([it.specs, it.config])), `${fid}: the other grade in what a website line stores`);
    }
  });

  describe('computeBasket: the standard configuration prices as before; a sheet approved against an older schema is "not approved"', () => {
    const prod = (id, formulaType, basePrice, dd, formula) => ({ id, category: 'prep_washing', name: id, formulaType, basePrice, defaultDimensions: dd, formula, specs: [], unit: 'pc' });
    const PRIM = {
      prep_table: prod('PW-001', 'per_length', 4217, { W: 900, D: 600, H: 850 }, { baseLengthMm: 900, pricePerExtraMm: 3.3, rateD100: 31, rateH100: 17 }),
      sink: prod('PW-004', 'per_length', 6173, { W: 500, D: 500, H: 850 }, { baseLengthMm: 500, pricePerExtraMm: 4.1, rateD100: 29, rateH100: 13 }),
      dish_table: prod('PW-029', 'fixed', 2719, { W: 1220, D: 660, H: 851 }, {}),                                                                                      // a FIXED base item: its length is priced from the sheet
      stove: prod('CE-001', 'per_length', 7770, { W: 600, D: 700, H: 850 }, { baseLengthMm: 600, pricePerExtraMm: 5.7, rateD100: 41, rateH100: 0 }),
      wok_range: prod('CE-006', 'per_length', 5233, { W: 600, D: 700, H: 850 }, { baseLengthMm: 600, pricePerExtraMm: 4.7, rateD100: 37, rateH100: 0 }),
    };
    const cell = (flat) => ({ flat, perW100: null });
    // fixture sheets (synthetic figures): an amount for one public option, and the 1.2 mm top cell left BLANK
    const SHEET = {
      prep_table: { options: { upper: { 1: cell(3077) }, top: { 1.2: cell(null) } }, option: ['upper', 1, 3077] },
      sink: { options: { faucet: { prerinse: cell(4519) }, top: { 1.2: cell(null) } }, option: ['faucet', 'prerinse', 4519] },
      dish_table: { options: { hand: { right: cell(1301) }, top: { 1.2: cell(null) } }, option: ['hand', 'right', 1301] },
      stove: { options: { addons: { oven: cell(22093) }, top: { 1.2: cell(null) } }, option: ['addons', ['oven'], 22093] },        // an oven adds no length (its width allowance is 0)
      wok_range: { options: { faucet: { swan: cell(3607) }, top: { 1.2: cell(null) } }, option: ['faucet', 'swan', 3607] },
    };
    const sheetDoc = (fid, schemaVersion) => ({ id: fid, data: { familyId: fid, schemaVersion, approved: true, approvedBy: 'u_syn', options: SHEET[fid].options, size: { perW100: fid === 'dish_table' ? 61 : null } } });
    const basket = (fid, config, schemaVersion) => {
      const r = norm(fid, config);
      assert.equal(r.ok, true, (r.errors || []).join(' '));
      return Q.computeBasket(r.items, new Map(), {}, undefined, { families: FAMS, primaries: new Map([[fid, PRIM[fid]]]), pricing: Q.buildPricingIndex([sheetDoc(fid, schemaVersion)], FAMS) }).lines[0];
    };

    it('the default configuration — top plate included — prices as the base item alone, and a public option adds exactly its amount: nothing changed for a visitor', () => {
      for (const fid of WITH_TOP) {
        const std = basket(fid, {}, FAMS.version);
        assert.equal(std.priced, true, fid);
        assert.equal(std.unitPrice, PRIM[fid].basePrice, `${fid}: the list price of the base item now buys the 1.5 mm top`);
        assert.deepEqual(std.deltas, []);
        assert.equal(basket(fid, { top: 1.5 }, FAMS.version).unitPrice, PRIM[fid].basePrice, `${fid}: stating the standard top changes nothing`);
        const [group, value, amount] = SHEET[fid].option;
        const withOption = basket(fid, { [group]: value }, FAMS.version);
        assert.equal(withOption.unitPrice, PRIM[fid].basePrice + amount, fid);
      }
    });

    it('a sheet approved against schema 1, 2, 3 or 4 (before the 1.5 mm top was the standard, before the five new families, before the steel grade, before the grade was a percentage) prices NOTHING — "priced after review" — until it is approved again; the same sheet at the current schema prices', () => {
      assert.equal(FAMS.version, 5, 'the family definitions are on schema 5 (the SS316 grade is a percentage of the whole line price)');
      for (const fid of WITH_TOP) {
        for (const older of [1, 2, 3, 4]) {
          const old = basket(fid, {}, older);
          assert.equal(old.priced, false, `${fid} at schema ${older}`); assert.equal(old.unitPrice, 0, fid);
          assert.equal(old.reason, 'not_approved', fid);
        }
        assert.equal(basket(fid, {}, FAMS.version).priced, true, `${fid}: the control — the current schema prices`);
        assert.equal(basket(fid, {}, FAMS.version + 1).reason, 'not_approved', `${fid}: and a FUTURE schema is just as unapproved`);
      }
    });
  });
});

// ── THE FIVE FAMILIES OF 2026-10-28 on the server (CONFIGURATOR-FAMILIES-2-SPEC §10.3) ─────────────────────────────────────────────────────────────────────────────────────────────────
// qrEstimate / qrSubmit validate every configured line with ProductFamilies.validateLine, so the new rules of the families are enforced here and nowhere else: an option that does not
// apply (fry baskets on a griddle, a pre-rinse sink on the clean side) is REFUSED with its message and the stored configuration is canonical; a size an option forces an UPPER limit on
// (a slim hood's depth, a deck oven's width) is refused; a width left out becomes the usual one for the options (a six-tray oven is 1200 mm wide); and the price of such a line is the
// primary SKU + the signed cells that APPLY. (Mutation-tested in scratch copies, cf2-ws1-mut/, each must fail here: validation keeping a non-applicable value; standardDims ignoring the
// forced minimum or maximum; validateDims taking the family default for a width left out; the forced maximum ignored or turned into a warning; forcedMaxes returning the minimums;
// pricing-core pricing the cell of an option that does not apply.) The kill switch productMeta/config families.disabled (functions/qr-core.js) is pinned in the next block.
describe('the five families of 2026-10-28 on the server: conditional options, upper limits, the usual width, and the price of what applies', () => {
  const primaries = new Map(FAMS.order.map((f) => [f, { id: FAMS.families[f].primary }]));
  const norm = (fid, config, dims) => Q.normaliseItems([{ familyId: fid, config, dims, qty: 1 }], byId, { families: FAMS, primaries });
  const ok = (fid, config, dims) => { const r = norm(fid, config, dims); assert.equal(r.ok, true, `${fid} ${JSON.stringify(config)} ${JSON.stringify(dims)}: ${(r.errors || []).join(' ')}`); return r.items[0]; };
  const refused = (fid, config, dims) => { const r = norm(fid, config, dims); assert.equal(r.ok, false, `${fid} ${JSON.stringify(config)} ${JSON.stringify(dims)} must be refused`); assert.deepEqual(r.items, []); return r.errors; };
  const label = (fid) => FAMS.families[fid].label;

  it('every one of the five is a quotable family: its defaults are accepted, stored canonically at the usual size, with the Construction row last', () => {
    for (const fid of ['dish_table', 'wok_range', 'cooking_line', 'deck_oven', 'hood']) {
      const it = ok(fid, {}, {});
      assert.equal(it.kind, 'family'); assert.equal(it.familyId, fid); assert.equal(it.id, FAMS.families[fid].primary);
      assert.equal(it.name, label(fid)); assert.equal(it.sizeCustom, false, `${fid}: the usual size is not a custom size`);
      assert.equal(it.cat, FAMS.families[fid].category);
      assert.deepEqual(Object.keys(it.size), Object.keys(FAMS.families[fid].dims), `${fid}: the family's own axes and nothing else (no height)`);
      assert.equal(it.specs.at(-1).label, 'Construction');
    }
    assert.equal(ok('hood', {}, {}).cat, 'ventilation');
  });

  it('a conditional option stated with a non-default value where it does not apply is REFUSED with its message, in any combination — and stated AT its default it is accepted and stored canonically', () => {
    assert.deepEqual(refused('cooking_line', { type: 'griddle', baskets: 3 }, { W: 700, D: 700 }), ['"Griddle, griller or fryer": "Fry baskets" applies only when Type is Fryer.']);
    assert.deepEqual(refused('cooking_line', { type: 'fryer', burners: 2 }, { W: 1000, D: 700 }), ['"Griddle, griller or fryer": "Burners" applies only when Type is Griddle or Lava-rock griller.']);
    assert.deepEqual(refused('cooking_line', { type: 'combi', burners: 3, baskets: 1 }, { W: 1200, D: 700 }).length, 2, 'both misused options are reported (the server shows the first two)');
    assert.deepEqual(refused('dish_table', { side: 'clean', sink: 'prerinse' }, { W: 1200, D: 660 }), ['"Dish table": "Pre-rinse sink" applies only when Side is Soiled.']);
    const fryer = ok('cooking_line', { type: 'fryer', baskets: 3 }, { W: 1000, D: 700 });
    assert.deepEqual(fryer.config, { grade: 304, type: 'fryer', burners: 1, baskets: 3, base: 'stand' }, 'the burners that do not apply are stored at their default');
    assert.deepEqual(fryer.specs.map((x) => x.label), ['Material', 'Type', 'Fry baskets', 'Base', 'Construction'], 'and have no row');
    assert.deepEqual(ok('cooking_line', { type: 'griddle', baskets: 2, burners: 2 }, { W: 900, D: 700 }).config, { grade: 304, type: 'griddle', burners: 2, baskets: 2, base: 'stand' }, 'stated at the default (2 baskets): accepted');
    // the same line hashes the same whether the option that does not apply is stated at its default or left out
    const h = (cfg) => Q.basketHash([ok('cooking_line', cfg, { W: 1000, D: 700 })]);
    assert.equal(h({ type: 'fryer', baskets: 3 }), h({ type: 'fryer', baskets: 3, burners: 1 }));
    assert.notEqual(h({ type: 'fryer', baskets: 3 }), h({ type: 'fryer', baskets: 2 }));
  });

  it('a size an option forces an UPPER limit on is refused: a slim hood 600 mm deep, a deck oven with three trays 800 wide or with six trays 1300 wide — and the limits themselves are accepted', () => {
    assert.deepEqual(refused('hood', { type: 'slim' }, { W: 1000, D: 600 }), ['"Range hood": With these options the depth must be at most 500 mm.']);
    assert.equal(ok('hood', { type: 'slim' }, { W: 1000, D: 500 }).size.D, 500);
    assert.equal(ok('hood', { type: 'wall' }, { W: 1000, D: 600 }).size.D, 600, 'a wall hood is not limited');
    assert.deepEqual(refused('deck_oven', { trays: 6 }, { W: 1300 }), ['"Gas deck oven": With these options the width must be at most 1200 mm.']);
    assert.deepEqual(refused('deck_oven', { trays: 3 }, { W: 800 }), ['"Gas deck oven": With these options the width must be at most 700 mm.']);
    assert.deepEqual(refused('deck_oven', { trays: 6 }, { W: 700 }), ['"Gas deck oven": With these options the width must be at least 1200 mm.']);
    assert.equal(ok('deck_oven', { trays: 6 }, { W: 1200 }).size.W, 1200);
    assert.equal(ok('deck_oven', { trays: 3 }, { W: 700 }).size.W, 700);
  });

  it('the lower limits: an island hood is at least 1200 long and 700 deep; a wok range needs 600 mm per hole (hard) and 800 mm of width for a rear burner; a pre-rinse sink needs 1200 mm; three burners need 1200, three baskets 1000, a combination 900', () => {
    assert.deepEqual(refused('hood', { type: 'island' }, { W: 1100, D: 900 }), ['"Range hood": With these options the length must be at least 1200 mm.']);
    assert.deepEqual(refused('hood', { type: 'island' }, { W: 1500, D: 650 }), ['"Range hood": With these options the depth must be at least 700 mm.']);
    assert.deepEqual(refused('hood', { type: 'wall' }, { W: 1000, D: 400 }), ['"Range hood": With these options the depth must be at least 500 mm.']);
    assert.match(refused('wok_range', { holes: 3 }, { W: 1700, D: 700 })[0], /The length must be at least 1800 mm for these wok holes\./);
    assert.equal(ok('wok_range', { holes: 3 }, { W: 1800, D: 700 }).size.W, 1800);
    assert.deepEqual(refused('wok_range', { rear: true }, { W: 600, D: 750 }), ['"Wok range": With these options the width must be at least 800 mm.']);
    assert.deepEqual(refused('dish_table', { side: 'soiled', sink: 'prerinse' }, { W: 1000, D: 660 }), ['"Dish table": With these options the length must be at least 1200 mm.']);
    assert.deepEqual(refused('cooking_line', { type: 'griddle', burners: 3 }, { W: 1000, D: 700 }), ['"Griddle, griller or fryer": With these options the length must be at least 1200 mm.']);
    assert.deepEqual(refused('cooking_line', { type: 'fryer', baskets: 3 }, { W: 900, D: 700 }), ['"Griddle, griller or fryer": With these options the length must be at least 1000 mm.']);
    assert.deepEqual(refused('cooking_line', { type: 'combi' }, { W: 800, D: 700 }), ['"Griddle, griller or fryer": With these options the length must be at least 900 mm.']);
  });

  it('a width or depth left out takes the size these options are normally built at: a six-tray deck oven with NO width is stored at 1200 mm (not the 700 mm default), a slim hood with no depth at 500, a three-wok range at 1800', () => {
    const six = ok('deck_oven', { trays: 6 }, undefined);
    assert.deepEqual(six.size, { W: 1200 }); assert.equal(six.sizeCustom, false);
    assert.deepEqual(ok('deck_oven', { trays: 6 }, {}).size, { W: 1200 });
    assert.deepEqual(ok('deck_oven', {}, {}).size, { W: 700 });
    assert.deepEqual(ok('hood', { type: 'slim' }, { W: 1400 }).size, { W: 1400, D: 500 });
    assert.deepEqual(ok('hood', { type: 'island' }, {}).size, { W: 1200, D: 900 });
    assert.deepEqual(ok('wok_range', { holes: 3 }, { D: 800 }).size, { W: 1800, D: 800 });
    assert.deepEqual(ok('cooking_line', { type: 'fryer', baskets: 3 }, {}).size, { W: 1000, D: 700 });
    assert.equal(ok('sink', { basins: 3 }, {}).size.W, 1500, 'and for the original families too: a three-sink table with no length is the usual 1500');
    // a custom size is still a custom size
    assert.equal(ok('deck_oven', {}, { W: 700 }).sizeCustom, false);
    assert.equal(ok('hood', {}, { W: 1100, D: 900 }).sizeCustom, true);
    assert.equal(ok('hood', { type: 'slim' }, { W: 1000, D: 400 }).sizeCustom, true);
  });

  describe('computeBasket: the primary SKU + the signed cells that APPLY — nothing for an option that does not', () => {
    const prod = (id, formulaType, basePrice, dd, formula) => ({ id, category: 'prep_washing', name: id, formulaType, basePrice, defaultDimensions: dd, formula, specs: [], unit: 'pc' });
    const PRIM = {
      cooking_line: prod('CE-010', 'per_length', 4349, { W: 700, D: 700, H: 850 }, { baseLengthMm: 700, pricePerExtraMm: 3.9, rateD100: 33, rateH100: 0 }),
      deck_oven: prod('CE-012', 'fixed', 9871, { W: 700, D: 700, H: 1400 }, {}),
      hood: prod('EX-001', 'per_length', 3571, { W: 1000, D: 900, H: 500 }, { baseLengthMm: 1000, pricePerExtraMm: 2.1, rateD100: 27, rateH100: 0 }),
    };
    const cell = (flat) => ({ flat, perW100: null });
    const SHEET = {
      cooking_line: { options: { type: { fryer: cell(1101), combi: cell(2203) }, burners: { 2: cell(307), 3: cell(611) }, baskets: { 1: cell(-409), 3: cell(823) }, base: { shelf: cell(517) } }, size: { perW100: null } },
      deck_oven: { options: { decks: { 1: cell(-3001), 3: cell(3011) }, trays: { 6: cell(4013) }, stand: { heavy: cell(1709) } }, size: { perW100: 0 } },
      hood: { options: { type: { island: cell(5701), slim: cell(-1301) }, filters: { none: cell(-701) }, lighting: { false: cell(-203) } }, size: { perW100: null } },
    };
    const doc = (fid, over) => ({ id: fid, data: { familyId: fid, schemaVersion: FAMS.version, approved: true, approvedBy: 'u_syn', ...SHEET[fid], ...(over || {}) } });
    const basket = (fid, config, dims, over) => {
      const r = norm(fid, config, dims);
      assert.equal(r.ok, true, (r.errors || []).join(' '));
      return Q.computeBasket(r.items, new Map(), {}, undefined, { families: FAMS, primaries: new Map([[fid, PRIM[fid]]]), pricing: Q.buildPricingIndex([doc(fid, over)], FAMS) }).lines[0];
    };

    it('a fryer with three baskets = the griddle + the fryer type + the 3-basket cell and NO burner cell; a griddle with three burners = the burner cell only; both agree with the base item\'s own length pricing', () => {
      const fryer = basket('cooking_line', { type: 'fryer', baskets: 3 }, { W: 1000, D: 700 });
      assert.equal(fryer.priced, true, fryer.missing.join(', '));
      assert.deepEqual(fryer.deltas.map((d) => d.key), ['type:fryer', 'baskets:3']);
      assert.equal(fryer.unitPrice, Math.round(4349 + (1000 - 700) * 3.9) + 1101 + 823);
      const griddle = basket('cooking_line', { type: 'griddle', burners: 3 }, { W: 1200, D: 700 });
      assert.deepEqual(griddle.deltas.map((d) => d.key), ['burners:3']);
      assert.equal(griddle.unitPrice, Math.round(4349 + (1200 - 700) * 3.9) + 611);
      const dflt = basket('cooking_line', {}, {});
      assert.deepEqual(dflt.deltas, []); assert.equal(dflt.unitPrice, 4349);
    });
    it('a six-tray oven at its 1200 mm prices the 6-tray cell + the width rate (0 = nothing); with NO width rate the line is "priced after review" naming "Size"; the three-tray default needs no rate', () => {
      const six = basket('deck_oven', { trays: 6 }, undefined);
      assert.equal(six.priced, true, six.missing.join(', '));
      assert.deepEqual(six.deltas.map((d) => d.key), ['trays:6', 'size:W']);
      assert.equal(six.unitPrice, 9871 + 4013);
      const noRate = basket('deck_oven', { trays: 6 }, undefined, { size: { perW100: null } });
      assert.equal(noRate.priced, false); assert.equal(noRate.reason, 'missing_input'); assert.deepEqual(noRate.missing, ['Size']); assert.equal(noRate.unitPrice, 0);
      const dflt = basket('deck_oven', {}, {}, { size: { perW100: null } });
      assert.equal(dflt.priced, true); assert.equal(dflt.unitPrice, 9871);
      assert.equal(basket('deck_oven', { decks: 3, stand: 'heavy' }, {}).unitPrice, 9871 + 3011 + 1709);
    });
    it('a hood: type, filters and lighting cells add up (a negative cell lowers the price); an unapproved sheet or a blank cell leaves the line "priced after review"', () => {
      const h = basket('hood', { type: 'island', filters: 'none', lighting: false }, { W: 1500, D: 900 });
      assert.equal(h.priced, true);
      assert.deepEqual(h.deltas.map((d) => d.key), ['type:island', 'filters:none', 'lighting:false']);
      assert.equal(h.unitPrice, Math.round(3571 + (1500 - 1000) * 2.1) + 5701 - 701 - 203);
      assert.equal(basket('hood', { type: 'wall' }, { W: 1000, D: 900 }).unitPrice, 3571);
      assert.equal(basket('hood', { type: 'slim' }, { W: 1000, D: 500 }).unitPrice, 3571 - 1301, 'the slim hood is shallower than the base: no depth discount, no depth surcharge');
      assert.equal(basket('hood', { type: 'wall' }, { W: 1000, D: 900 }, { approved: false }).reason, 'not_approved');
      const blank = basket('hood', { type: 'wall', filters: 'none' }, { W: 1000, D: 900 }, { options: { ...SHEET.hood.options, filters: { none: cell(null) } } });
      assert.equal(blank.priced, false); assert.deepEqual(blank.missing, ['Grease filters: None (open canopy)']);
    });
  });
});

// ── THE PER-FAMILY KILL SWITCH (CONFIGURATOR-FAMILIES-2-SPEC §9, WS-2) ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────
// productMeta/config.families.disabled is a list of family ids the owner can switch OFF on the website with no deploy. qrLoadProducts caches disabledFamiliesOf(meta) beside the estimate switch and
// BOTH callables (qrEstimate, qrSubmit) hand it to normaliseItems: a listed family is refused with the very same message an unknown family gets (the page then removes the line) and its id comes back
// in `badIds`; nothing else about the line is validated or priced. A malformed list can only ever leave a family ON (the same fail-open reading as estimateEnabledOf). The end-to-end run through the
// callables is in tests/quote-request-callables.test.mjs.
// Mutation-tested in a scratch copy (cf2-ws2-mut/, 22 server mutants of the switch, all killed; each must fail here): disabledFamiliesOf returning [] / reading the wrong key / keeping non-string or empty entries /
// not de-duplicating / accepting a bare string / folding case or trimming / handing back the document's own array / not exported; normaliseItems ignoring the list / refusing EVERY family as soon as one is listed /
// refusing only the first listed one / not understanding a Set / validating the line before the gate / not reporting the id in badIds / answering with a message of its own; the products cache not keeping the list, the stale-cache
// path dropping it, qrEstimate or qrSubmit not passing it, or passing it in the wrong form.
describe('the per-family kill switch (productMeta/config families.disabled): a listed family is refused like an unknown one, and a malformed list switches nothing off', () => {
  const primaries = new Map(FAMS.order.map((f) => [f, { id: FAMS.families[f].primary }]));
  const line = (fid, config, dims) => ({ familyId: fid, config: config || {}, dims: dims || {}, qty: 1 });
  const norm = (items, disabled) => Q.normaliseItems(items, byId, { families: FAMS, primaries, ...(disabled === undefined ? {} : { disabledFamilies: disabled }) });

  it('disabledFamiliesOf reads productMeta/config.families.disabled: the distinct non-empty string entries in the order written; no document, no list or a malformed one -> []', () => {
    for (const meta of [undefined, null, {}, [], 'x', 7, { families: null }, { families: [] }, { families: 'hood' }, { families: {} }, { families: { disabled: null } }, { families: { disabled: [] } }, { constants: { disabled: ['hood'] } }, { disabled: ['hood'] }]) {
      assert.deepEqual(Q.disabledFamiliesOf(meta), [], JSON.stringify(meta));
    }
    assert.deepEqual(Q.disabledFamiliesOf({ families: { disabled: ['hood'] } }), ['hood']);
    assert.deepEqual(Q.disabledFamiliesOf({ families: { disabled: ['hood', 'deck_oven', 'hood'] } }), ['hood', 'deck_oven'], 'distinct, in the order written');
    assert.deepEqual(Q.disabledFamiliesOf({ families: { disabled: ['hood', 7, null, undefined, '', { id: 'sink' }, ['sink'], true, 'wok_range'] } }), ['hood', 'wok_range'], 'only real, non-empty strings count');
    // the entries are EXACT ids: no trimming, no case folding (the Quote Builder compares the same list the same way) — so a mistyped entry disables nothing
    assert.deepEqual(Q.disabledFamiliesOf({ families: { disabled: ['Hood', ' hood', 'HOOD'] } }), ['Hood', ' hood', 'HOOD']);
    // `disabled` must be a LIST: a bare string, an object (even an array-like one) or a number switches nothing off
    for (const bad of ['hood', { hood: true }, { 0: 'hood', length: 1 }, 7, true]) assert.deepEqual(Q.disabledFamiliesOf({ families: { disabled: bad } }), [], JSON.stringify(bad));
    // the answer is a fresh array: changing it can never change the document it was read from
    const meta = { families: { disabled: ['hood'] } };
    Q.disabledFamiliesOf(meta).push('sink');
    assert.deepEqual(meta.families.disabled, ['hood']);
  });

  it('a listed family is refused with the message and shape an unknown family gets — GONE_MSG once, the id in badIds, nothing stored — whether the list is an array or a Set', () => {
    const unknown = norm([line('toaster')]);
    assert.deepEqual(unknown.errors, [Q.GONE_MSG]);
    for (const list of [['hood'], new Set(['hood'])]) {
      const r = norm([line('hood')], list);
      assert.equal(r.ok, false);
      assert.deepEqual(r.errors, unknown.errors, 'the very same message');
      assert.deepEqual(r.badIds, ['hood']);
      assert.deepEqual(r.items, []);
    }
    // several at once: the message appears once, every id is reported, in the order of the basket
    const two = norm([line('hood'), line('sink'), line('deck_oven'), { id: 'S-FIX', qty: 1 }], ['deck_oven', 'hood']);
    assert.equal(two.ok, false);
    assert.deepEqual(two.errors, [Q.GONE_MSG]);
    assert.deepEqual(two.badIds, ['hood', 'deck_oven']);
    // the same basket without them is fine: the other families and the plain lines are untouched
    assert.equal(norm([line('sink'), { id: 'S-FIX', qty: 1 }], ['deck_oven', 'hood']).ok, true);
  });

  it('exactly the listed family is off: for EACH of the eleven, switching it off refuses that family and no other', () => {
    for (const off of FAMS.order) {
      for (const fid of FAMS.order) {
        const r = norm([line(fid)], [off]);
        if (fid === off) { assert.equal(r.ok, false, `${off} must be refused`); assert.deepEqual(r.badIds, [off]); }
        else assert.equal(r.ok, true, `${fid} must stay on while only ${off} is off: ${(r.errors || []).join(' ')}`);
      }
    }
  });

  it('nothing is switched off by: no option, an empty array or Set, a bare string, a number, an object, null, an id that is not a family, or a mistyped one (exact ids only)', () => {
    for (const none of [undefined, [], new Set(), 'hood', 7, {}, null, ['toaster'], ['Hood', ' hood', 'HOOD', 'hood '], new Set(['Hood'])]) {
      assert.equal(norm([line('hood')], none).ok, true, JSON.stringify(none));
    }
  });

  it('a listed family is refused BEFORE its line is checked or priced: a malformed configuration, a wrong quantity or a staff-only option still gets the plain "no longer in the catalogue" answer (its rules are never probed)', () => {
    for (const raw of [line('hood', { type: 'castle' }, { W: 1 }), { ...line('hood'), qty: 0 }, line('hood', { top: 1.2 }), line('hood', { filters: 'none' }, { W: 99999 })]) {
      assert.notDeepEqual(norm([raw]).errors, [Q.GONE_MSG], 'sanity: while the family is on, this line fails its own validation: ' + JSON.stringify(raw));
      const r = norm([raw], ['hood']);
      assert.deepEqual(r.errors, [Q.GONE_MSG], JSON.stringify(raw));
      assert.deepEqual(r.badIds, ['hood']);
    }
  });

  it('the composition the callables use — the list read from the document, then handed to normaliseItems — switches the family off', () => {
    const meta = { constants: { materialPriceIndexMultiplier: 1 }, families: { disabled: ['cooking_line'] } };
    const opts = { families: FAMS, primaries, disabledFamilies: Q.disabledFamiliesOf(meta) };
    assert.equal(Q.normaliseItems([line('cooking_line')], byId, opts).ok, false);
    assert.equal(Q.normaliseItems([line('wok_range')], byId, opts).ok, true);
    assert.equal(Q.normaliseItems([line('cooking_line')], byId, { ...opts, disabledFamilies: Q.disabledFamiliesOf({ ...meta, families: { disabled: [] } }) }).ok, true, 'taking it off the list brings it back');
  });

  it('the callables wire it: qrLoadProducts caches disabledFamiliesOf(productMeta/config) and BOTH qrEstimate and qrSubmit hand the cached list to normaliseItems — and no third place normalises a basket', () => {
    const src = read('functions/index.js');
    assert.equal((src.match(/disabledFamilies: qr\.disabledFamiliesOf\(meta\)/g) || []).length, 1, 'the products cache must keep the list read from productMeta/config');
    const calls = src.match(/qr\.normaliseItems\([^;]*\);/g) || [];
    assert.equal(calls.length, 2, 'qrEstimate and qrSubmit are the only callables that normalise a basket');
    for (const c of calls) assert.match(c, /disabledFamilies: products\.disabledFamilies/, c);
    assert.match(src, /exports\.qrEstimate[\s\S]*?qr\.normaliseItems\([^;]*products\.disabledFamilies[^;]*\);[\s\S]*?exports\.qrSubmit[\s\S]*?qr\.normaliseItems\([^;]*products\.disabledFamilies[^;]*\);/, 'one call in each of the two callables');
  });
});

describe('sessions, the bot check, duplicates, the LRU and the product cache', () => {
  it('sessionUsable: exists, unsubmitted, created within the 7-day TTL', () => {
    const t = NOW - 1000;
    assert.equal(Q.sessionUsable({ submittedAt: null }, t, NOW), true);
    assert.equal(Q.sessionUsable(null, t, NOW), false);
    assert.equal(Q.sessionUsable({ submittedAt: new Date() }, t, NOW), false);
    assert.equal(Q.sessionUsable({ submittedAt: null }, 0, NOW), false);
    assert.equal(Q.sessionUsable({ submittedAt: null }, NOW - LIMITS.sessionTtlMs, NOW), true);
    assert.equal(Q.sessionUsable({ submittedAt: null }, NOW - LIMITS.sessionTtlMs - 1, NOW), false);
  });
  it('sessionEstimateDecision: 150 per 24 h, then blocked; a quiet day opens a fresh window; never throws', () => {
    const d = (count, lastMs) => Q.sessionEstimateDecision({ estimateCount: count, lastEstimateMs: lastMs }, NOW, 'h');
    assert.deepEqual(d(0, null), { allowed: true, next: { estimateCount: 1, lastBasketHash: 'h' } });
    assert.deepEqual(d(149, NOW - 1000), { allowed: true, next: { estimateCount: 150, lastBasketHash: 'h' } });
    assert.deepEqual(d(150, NOW - 1000), { allowed: false, next: null });
    assert.deepEqual(d(999, NOW - 23 * 3600e3), { allowed: false, next: null });
    assert.deepEqual(d(150, NOW - 24 * 3600e3), { allowed: true, next: { estimateCount: 1, lastBasketHash: 'h' } });
    assert.equal(Q.sessionEstimateDecision(null, NOW).allowed, true);
    assert.equal(Q.sessionEstimateDecision({ estimateCount: 'x' }, NOW).next.estimateCount, 1);
  });
  it('botCheck: a non-empty honeypot, or < 20 s after the session was created, is a bot', () => {
    assert.deepEqual(Q.botCheck({ honeypot: 'http://spam', sessionCreatedMs: NOW - 99999, nowMs: NOW }), { bot: true, reason: 'honeypot' });
    assert.deepEqual(Q.botCheck({ honeypot: '', sessionCreatedMs: NOW - 19999, nowMs: NOW }), { bot: true, reason: 'too_fast' });
    assert.deepEqual(Q.botCheck({ honeypot: '', sessionCreatedMs: NOW - 20000, nowMs: NOW }), { bot: false, reason: null });
    assert.deepEqual(Q.botCheck({ honeypot: '   ', sessionCreatedMs: NOW - 30000, nowMs: NOW }), { bot: false, reason: null });
    assert.equal(Q.botCheck({ honeypot: '', sessionCreatedMs: NaN, nowMs: NOW }).bot, true);
    assert.equal(Q.botCheck({}).bot, true);
    assert.equal(LIMITS.minFillMs, 20000);
  });
  it('fingerprintDay: deterministic, case/space-insensitive on the e-mail, digits-only on the mobile, tied to the Manila day', () => {
    const a = Q.fingerprintDay('Juan@Example.com ', '0917 123 4567', '2026-10-21');
    assert.equal(a, Q.fingerprintDay('juan@example.com', '09171234567', '2026-10-21'));
    assert.notEqual(a, Q.fingerprintDay('juan@example.com', '09171234568', '2026-10-21'));
    assert.ok(a.endsWith('|2026-10-21'));
    assert.match(a, /^[0-9a-f]{64}\|2026-10-21$/);
  });
  it('createLru: bounded, TTL-expiring, recency-refreshing', () => {
    const lru = Q.createLru(3, 1000);
    lru.set('a', 1, 0); lru.set('b', 2, 0); lru.set('c', 3, 0);
    assert.equal(lru.get('a', 10), 1);               // a is now the most recent
    lru.set('d', 4, 20);                             // evicts the least recent: b
    assert.equal(lru.get('b', 20), undefined);
    assert.equal(lru.get('a', 20), 1);
    assert.equal(lru.size, 3);
    assert.equal(lru.get('c', 2000), undefined);     // expired
    assert.equal(lru.get('zzz', 0), undefined);
  });
  it('productsCacheState: fresh < 10 min, stale < 24 h (may cover a failed refresh), dead after, empty with none', () => {
    const c = (age) => ({ loadedAt: NOW - age });
    assert.equal(Q.productsCacheState(null, NOW), 'empty');
    assert.equal(Q.productsCacheState({}, NOW), 'empty');
    assert.equal(Q.productsCacheState(c(0), NOW), 'fresh');
    assert.equal(Q.productsCacheState(c(Q.PRODUCTS_TTL_MS - 1), NOW), 'fresh');
    assert.equal(Q.productsCacheState(c(Q.PRODUCTS_TTL_MS), NOW), 'stale');
    assert.equal(Q.productsCacheState(c(24 * 3600e3 - 1), NOW), 'stale');
    assert.equal(Q.productsCacheState(c(24 * 3600e3), NOW), 'dead');
    assert.equal(Q.PRODUCTS_TTL_MS, 600000);
  });
  it('the kill-switch (O7) is on unless productMeta/config.quoteRequest.estimateEnabled === false; constants default to {}', () => {
    assert.equal(Q.estimateEnabledOf(undefined), true);
    assert.equal(Q.estimateEnabledOf({}), true);
    assert.equal(Q.estimateEnabledOf({ quoteRequest: {} }), true);
    assert.equal(Q.estimateEnabledOf({ quoteRequest: { estimateEnabled: true } }), true);
    assert.equal(Q.estimateEnabledOf({ quoteRequest: { estimateEnabled: false } }), false);
    assert.equal(Q.estimateEnabledOf({ quoteRequest: { estimateEnabled: 'false' } }), true);          // only a real boolean false switches it off
    assert.deepEqual(Q.constantsOf(undefined), {});
    assert.deepEqual(Q.constantsOf({ constants: { materialPriceIndexMultiplier: 1.07 } }), { materialPriceIndexMultiplier: 1.07 });
    assert.deepEqual(Q.constantsOf({ constants: 'x' }), {});
  });
});

describe('rate limits — spec §5.1 (pinned)', () => {
  it('per-IP and global caps, fail-closed windows', () => {
    const R = Q.RATE;
    assert.deepEqual(R.start, { window: 3600e3, max: 20, lock: 3600e3, maxLock: 24 * 3600e3 });
    assert.deepEqual(R.globalStart, { window: 3600e3, max: 300, lock: 1800e3, maxLock: 6 * 3600e3 });
    assert.deepEqual(R.estimate, { window: 3600e3, max: 60, lock: 3600e3, maxLock: 24 * 3600e3 });
    assert.deepEqual(R.estimateSession, { window: 24 * 3600e3, max: 150 });
    assert.deepEqual(R.globalEstimate, { window: 3600e3, max: 2000, lock: 900e3, maxLock: 2 * 3600e3 });
    assert.deepEqual(R.submit, { window: 24 * 3600e3, max: 5, lock: 24 * 3600e3, maxLock: 7 * 24 * 3600e3 });
    assert.deepEqual(R.globalSubmit, { window: 3600e3, max: 40, lock: 1800e3, maxLock: 6 * 3600e3 });
  });
  it('the estimate bucket really does stop the 60th probe from an IP (rateLimitDecision reused, not reimplemented)', () => {
    let bucket = null;
    let allowed = 0;
    for (let i = 0; i < 70; i++) {
      const d = portal.rateLimitDecision(bucket, NOW + i, Q.RATE.estimate);
      if (d.allowed) allowed++;
      bucket = d.next;
    }
    assert.equal(allowed, 60);
  });
});

describe('buildSummary / buildNotification — R6', () => {
  const contact = { name: 'Juan Dela Cruz', company: 'JDC Foods', mobile: '09171234567', email: 'juan@example.com' };
  const intake = { need: 'equipment', useFor: 'restaurant_cafe', entityType: 'private', targetDate: '2026-12-01' };
  it('buildSummary: strings "" when blank, numbers null when no figure is shown', () => {
    const shown = Q.buildSummary({ contact, intake, itemCount: 3, estimate: { shown: true, low: 10000, high: 15000 } });
    assert.deepEqual(shown, { name: 'Juan Dela Cruz', company: 'JDC Foods', mobile: '09171234567', email: 'juan@example.com', need: 'equipment', useFor: 'restaurant_cafe', entityType: 'private', targetDate: '2026-12-01', itemCount: 3, estimateLow: 10000, estimateHigh: 15000, estimateShown: true });
    const hidden = Q.buildSummary({ contact: { ...contact, company: '' }, intake: { ...intake, targetDate: null }, itemCount: 1, estimate: { shown: false, low: null, high: null } });
    assert.equal(hidden.company, '');
    assert.equal(hidden.targetDate, '');
    assert.equal(hidden.estimateLow, null);
    assert.equal(hidden.estimateHigh, null);
    assert.equal(hidden.estimateShown, false);
    assert.deepEqual(Q.buildSummary({}).itemCount, 0);
  });
  it('buildNotification: plain emoji, caps respected, type / link / icon, and the figure only as the rounded range', () => {
    const doc = { refNo: 'QR-261021-ABCDEF', summary: Q.buildSummary({ contact, intake, itemCount: 3, estimate: { shown: true, low: 75000, high: 100000 } }) };
    const n = Q.buildNotification(doc);
    assert.deepEqual(Object.keys(n).sort(), ['body', 'icon', 'link', 'title', 'type']);
    assert.equal(n.title, '🧾 New quote request — JDC Foods');
    assert.equal(n.body, 'Juan Dela Cruz · Individual kitchen equipment · Restaurant / café · 3 items · est. ₱75,000–₱100,000 · Ref QR-261021-ABCDEF. Open Sales → Quote requests.');
    assert.equal(n.icon, '🧾');
    assert.equal(n.type, 'quote_request');
    assert.equal(n.link, 'dept:Sales');
    assert.ok(n.title.length <= 200 && n.body.length <= 2000);
    assert.ok(!/<i |data-lucide|emojiIcon/.test(n.title + n.body + n.icon), 'markup in a plain-text sink');
  });
  it('buildNotification: no estimate -> no figure; a single item reads "1 item"; falls back to the name', () => {
    const doc = { refNo: 'QR-261021-ABCDEF', summary: Q.buildSummary({ contact: { ...contact, company: '' }, intake, itemCount: 1, estimate: { shown: false } }) };
    const n = Q.buildNotification(doc);
    assert.equal(n.title, '🧾 New quote request — Juan Dela Cruz');
    assert.ok(n.body.includes(' · 1 item · Ref'));
    assert.ok(!n.body.includes('₱'));
  });
  it('buildNotification: attacker text can never carry "<" or a control character, and is capped', () => {
    const evil = '<img src=x onerror=alert(1)>\u0007' + 'A'.repeat(400);
    const doc = { refNo: 'QR-261021-ABCDEF', summary: { name: evil, company: evil, need: 'equipment', useFor: 'home', itemCount: 2, estimateShown: false } };
    const n = Q.buildNotification(doc);
    assert.ok(!/[<\x00-\x1F\x7F]/.test(n.title + n.body), 'unsafe character survived');
    assert.ok(n.title.length <= 200 && n.body.length <= 2000);
  });
  it('buildNotification NEVER carries the internal exact figure (lock screens show push bodies)', () => {
    const doc = { refNo: 'QR-261021-ABCDEF', summary: Q.buildSummary({ contact, intake, itemCount: 2, estimate: { shown: true, low: 75000, high: 100000 } }), internal: { exactTotal: 84123, lines: [{ unitPrice: 42061 }] } };
    const n = JSON.stringify(Q.buildNotification(doc));
    for (const s of ['84123', '84,123', '42061', '42,061']) assert.ok(!n.includes(s), `${s} leaked into the notification`);
  });
});

