// ── source-level pins on functions/index.js (the glue is tested end to end in quote-request-callables.test.mjs) ──
describe('js/quote-request.js — the page logic that must AGREE with the server, taken from the real source', () => {
  const PRICING = require('../functions/pricing-core.js');
  const src = read('js/quote-request.js');
  // Pull a named function (brace-matched) out of the IIFE so the REAL code is what is tested, not a copy.
  function grab(name) {
    const start = src.indexOf(`function ${name}(`);
    assert.ok(start >= 0, `function ${name} not found in js/quote-request.js`);
    let i = src.indexOf('{', start), depth = 0;
    for (; i < src.length; i++) { if (src[i] === '{') depth++; else if (src[i] === '}') { depth--; if (!depth) break; } }
    return src.slice(start, i + 1);
  }
  const sandbox = (names, extra) => {
    const ctx = vm.createContext(Object.assign({ LIMITS, Object, Array, Math, JSON }, extra || {}));
    vm.runInContext(names.map(grab).join('\n'), ctx);
    return ctx;
  };

  it('maxDim / isFixedDim match the server\'s validateSelection for every default size: the largest accepted custom size, and "fixed" exactly when none exists', () => {
    const ctx = sandbox(['maxDim', 'isFixedDim']);
    const defaults = [20, 25, 30, 33, 34, 40, 90, 100, 110, 475, 900, 2000, 2999, 3000, 3001, 3454, 3500, 5999, 6000, 6001, 6858, 10000];
    let checked = 0;
    for (const k of ['W', 'D', 'H']) {
      for (const def of defaults) {
        const p = { id: 'P', formulaType: 'fixed', basePrice: 1, unit: 'pc', defaultDimensions: { [k]: def }, formula: {}, specs: [] };
        const mx = ctx.maxDim({ dims: { [k]: def } }, k);
        const accepts = (n) => PRICING.validateSelection(p, { size: { [k]: n } }, LIMITS).ok;
        // the default itself is always accepted; the page's maximum is accepted unless it IS fixed
        assert.equal(accepts(def), true, `${k}=${def}: default`);
        let largest = null;
        for (let n = LIMITS.minDimMm; n <= Math.max(mx, def) + 20; n += LIMITS.dimStepMm) { if (n !== def && accepts(n)) largest = n; }
        if (ctx.isFixedDim({ dims: { [k]: def } }, k)) assert.equal(largest, null, `${k}=${def} is fixed on the page, so the server must accept no custom size (it accepted ${largest})`);
        else {
          // the page offers [min, mx]: the server accepts the greatest multiple of the step that is <= mx, and nothing above it (bar the default itself)
          const expected = Math.floor(mx / LIMITS.dimStepMm) * LIMITS.dimStepMm;
          assert.equal(accepts(expected), true, `${k}=${def}: the page maximum ${mx} (${expected}) must be accepted`);
          assert.equal(accepts(LIMITS.minDimMm), true, `${k}=${def}: the minimum must be accepted`);
          for (let n = expected + LIMITS.dimStepMm; n <= expected + 20 * LIMITS.dimStepMm; n += LIMITS.dimStepMm) assert.equal(accepts(n), n === def, `${k}=${def}: ${n} is above the page maximum ${mx}`);
        }
        checked++;
      }
    }
    assert.ok(checked >= 60);
  });

  it('capUnits (a loaded or merged draft) leaves a list the server accepts: one product, one multiplier — qty and runs, any number of lines', () => {
    const ctx = sandbox(['capUnits', 'unitKey', 'isFam'], {});
    let seed = 0x9E3779B9;
    const rnd = () => { seed ^= seed << 13; seed >>>= 0; seed ^= seed >>> 17; seed ^= seed << 5; seed >>>= 0; return seed / 4294967296; };
    for (let t = 0; t < 400; t++) {
      const items = Array.from({ length: 1 + Math.floor(rnd() * 40) }, (_, i) => {
        const run = rnd() < 0.3;
        const id = run ? 'S-RUN' : (rnd() < 0.5 ? 'S-FIX' : 'S-LEN');
        return run ? { uid: 'u' + i, id, qty: 1, runs: 1 + Math.floor(rnd() * 20), size: null, specs: [] } : { uid: 'u' + i, id, qty: 1 + Math.floor(rnd() * 20), runs: null, size: null, specs: [] };
      });
      const out = ctx.capUnits(JSON.parse(JSON.stringify(items)));
      const wire = out.items.map((it) => ({ id: it.id, qty: it.qty, size: null, runs: it.runs, specs: [], note: '' }));
      if (!wire.length) continue;
      const r = Q.normaliseItems(wire, byId);
      assert.equal(r.ok, true, `capUnits left a list the server refuses: ${r.errors.join(' | ')}`);
    }
    // and it never touches a list that is already within the cap
    const fine = [{ uid: 'a', id: 'S-FIX', qty: 10, runs: null }, { uid: 'b', id: 'S-FIX', qty: 10, runs: null }, { uid: 'c', id: 'S-NOD', qty: 20, runs: null }];
    assert.deepEqual(JSON.parse(JSON.stringify(ctx.capUnits(JSON.parse(JSON.stringify(fine))))), { items: fine, dropped: 0 });
  });

  it('pins that keep the review fixes from regressing (the page is not unit-testable in plain Node, so the shape of the fix is pinned in the source)', () => {
    // an estimate never carries the free-text note
    assert.ok(!/function estimateItemPayload\(it\)[^}]*note/.test(src), 'the estimate payload must not include the note');
    assert.match(src, /draft\.items\.map\(estimateItemPayload\)/);
    // submitting locks the sheet and the receipt is built from the snapshot taken at the click
    assert.match(src, /submitting = b; sheet\.closable = !b;/);
    assert.match(src, /\[f\.head, f\.body\]\.forEach\(function \(n\) \{ if \(b\) n\.setAttribute\('inert', ''\)/);
    assert.match(src, /var snap = \{ items: clone\(draft\.items\), intake: clone\(draft\.intake\), contact: clone\(draft\.contact\)/);
    assert.match(src, /\.then\(function \(res\) \{\s+setBusy\(false\);\s+onSubmitted\(res, snap\);/);                 // the CALL site, not just the definition
    assert.match(src, /clearTimeout\(estTimer\); estSeq\+\+;\s+\/\/ a pending or in-flight estimate must not outlive/);
    // the wait before sending is bounded and uses the token it was measured for
    assert.match(src, /Math\.min\(floor, floor - \(Date\.now\(\) - \(draft\.sessionLocalAtMs \|\| 0\)\)\)/);
    assert.match(src, /Qr\.submit\(Object\.assign\(\{ sessionToken: token \}, payloadBase\)\)/);
    // stored clocks are validated on load; another tab clearing the draft resets this tab
    assert.match(src, /localAt <= Date\.now\(\)/);
    assert.match(src, /window\.addEventListener\('storage'/);
    // everything in #site (skip link included) goes inert behind a dialog; the live region persists; the label contains the visible text
    assert.match(src, /site\.children\)\.filter\(function \(n\) \{ return n !== root && !n\.contains\(root\); \}\)/);
    assert.match(src, /estBox = el\('div', \{ 'aria-live': 'polite' \}\)/);
    assert.match(src, /'aria-label': 'Add to quote: ' \+ p\.name/);
    // an estimate that failed offline is retried on reconnect
    assert.match(src, /est\.status === 'error' && draft\.items\.length && !submitting\) scheduleEstimate\(\)/);
    // the duplicate-line prompt re-reads the form at the click
    assert.match(src, /var finish = function \(mode\) \{ var again = build\(\); if \(again\) commit\(again, mode\); \};/);
    // no price vocabulary and no innerHTML crept in
    const code = src.replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[^:])\/\/.*$/gm, '$1');            // comments may say "never innerHTML"
    assert.ok(!/innerHTML|insertAdjacentHTML|document\.write|eval\(|new Function/.test(code), 'markup injection or code evaluation crept into the public page');
  });
});

describe('Sales › Quote requests screen (js/screens/quote-requests.js) — hostile content is inert; handlers carry only the server-minted ref', () => {
  // The REAL escHtml (js/modules.js) and the REAL screen source, run in a vm sandbox with a stub `window`.
  const escSrc = read('js/modules.js').match(/function escHtml\(str\) \{[\s\S]*?\n\}/)[0];
  const sandbox = (role, depts) => {
    const ctx = vm.createContext({ window: { currentRole: role, currentDepts: depts || [], QR_DEF: QR, bizDate: () => '2026-10-21', renderEmptyState: (o) => `<div>${o.title}</div>` }, emojiIcon: (g) => `[${g}]`, console });
    vm.runInContext(escSrc, ctx);
    vm.runInContext(read('js/screens/quote-requests.js'), ctx);
    return ctx;
  };
  const ctx = sandbox('president');
  const HOSTILE = '<img src=x onerror=window.__xss=1>"\'><script>window.__xss=2</script></td><svg onload=window.__xss=3>';
  const row = (over) => Object.assign({ id: 'QR-261021-AAAAAA', submittedOnManila: '2026-10-21', createdAt: null, status: 'new', summary: { name: HOSTILE, company: HOSTILE, mobile: HOSTILE, email: HOSTILE, entityType: 'private', need: HOSTILE, useFor: HOSTILE, itemCount: 2, estimateShown: true, estimateLow: 10000, estimateHigh: 20000 } }, over || {});

  it('_qrRefAttr accepts ONLY the server-minted reference and renders anything else as an empty string', () => {
    assert.equal(ctx._qrRefAttr('QR-261021-AHUKDX'), 'QR-261021-AHUKDX');
    for (const bad of ["QR-261021-AAAAAA'),alert(1),('", 'QR-261021-AAAAAA ', 'qr-261021-aaaaaa', 'QR-26102-AAAAAA', '', null, undefined, '<img>', 'QR-261021-AAAAA<', "x' onclick='y"]) {
      assert.equal(ctx._qrRefAttr(bad), '', String(bad));
    }
  });
  it('the list: every visitor-supplied string is HTML-escaped (no tag, no attribute breakout) and the row handler is qrOpen(<safe ref>) only', () => {
    const html = ctx._qrTableHtml([row()]);
    assert.ok(!/<img|<svg|<script/.test(html), 'a visitor-supplied tag was parsed as markup');
    assert.ok(html.includes('onclick="qrOpen(\'QR-261021-AAAAAA\')"'));
    const evil = ctx._qrTableHtml([row({ id: "QR-261021-AAAAAA');window.__xss=9;('" })]);
    assert.ok(evil.includes('onclick="qrOpen(\'\')"'), 'a hostile id must never reach an inline handler');
    assert.ok(!evil.includes('onclick="qrOpen(\'QR-261021-AAAAAA\');'));
  });
  it('the estimate card labels the visitor\'s own figure as client-reported / unverified and warns when the server disagrees', () => {
    const base = { estimate: { shown: true, low: 10000, high: 20000, step: 5000, pricedCount: 2, reviewCount: 0, customSizeCount: 0 }, estimateVersion: 1, lastEstimate: { low: 1, high: 2, basketHash: 'a'.repeat(64) } };
    const ok = ctx._qrEstimateCardHtml(Object.assign({}, base, { estimateMismatch: false }));
    assert.match(ok, /Client saw:/);
    assert.match(ok, /Client-reported last figure \(unverified\)/);
    assert.ok(!/does not match the figure computed at submission/.test(ok));
    const bad = ctx._qrEstimateCardHtml(Object.assign({}, base, { estimateMismatch: true }));
    assert.match(bad, /does not match the figure computed at submission/);
    assert.match(bad, /rely on the figure above/);
    const hostile = ctx._qrEstimateCardHtml({ estimate: { shown: false, reason: HOSTILE }, estimateVersion: HOSTILE, lastEstimate: { low: '<b>x</b>', high: HOSTILE } });
    assert.ok(!/<b>|<img|<script|<svg/.test(hostile), 'a hostile estimate field was parsed as markup');
  });
  it('role gating: write = president / manager / owner or a NON-secretary Sales member; the secretary never writes (even in Sales); delete = president / manager / owner only', () => {
    const w = (role, depts) => sandbox(role, depts).qrCanWrite();
    const d = (role, depts) => sandbox(role, depts).qrCanDelete();
    assert.deepEqual(['president', 'manager', 'owner'].map((r) => w(r, [])), [true, true, true]);
    assert.equal(w('employee', ['Sales']), true);
    assert.equal(w('employee', ['Design']), false);
    assert.equal(w('employee', []), false);
    assert.equal(w('secretary', ['Sales']), false);
    assert.deepEqual(['president', 'manager', 'owner'].map((r) => d(r, ['Sales'])), [true, true, true]);
    assert.equal(d('employee', ['Sales']), false);
    assert.equal(d('secretary', ['Sales']), false);
    assert.equal(d('finance', ['Sales']), false);
  });
});

describe('functions/index.js — the qr* glue stays inside the rules', () => {
  const src = read('functions/index.js');
  const block = (from, to) => { const a = src.indexOf(from); const b = src.indexOf(to, a + 1); assert.ok(a > 0 && b > a, `cannot find ${from}`); return src.slice(a, b); };
  const est = block('exports.qrEstimate = functions', '// ── qrSubmit');
  const sub = block('exports.qrSubmit = functions', '// ── qrAdminDelete');

  it('exports exactly the four callables, all in asia-east1', () => {
    for (const n of ['qrStartSession', 'qrEstimate', 'qrSubmit', 'qrAdminDelete']) {
      assert.match(src, new RegExp(`exports\\.${n} = functions\\s*\\n\\s*\\.region\\('asia-east1'\\)\\s*\\n\\s*\\.https\\.onCall`), n);
    }
    assert.equal((src.match(/exports\.qr[A-Za-z]+ = /g) || []).length, 4);
  });
  it('qrEstimate\'s every return is qr.publicEstimate(...) (or a transaction verdict) — never an object built here', () => {
    const returns = [...est.matchAll(/\breturn\b[^\n]*/g)].map((m) => m[0].trim());
    assert.ok(returns.length >= 4);
    for (const r of returns) assert.ok(/^return (qr\.publicEstimate\(|\{ outcome: )/.test(r), `unexpected return in qrEstimate: ${r}`);
    assert.ok(returns.filter((r) => r.startsWith('return qr.publicEstimate(')).length >= 2);
    // the exact total may be READ to derive the rounded range, but it is never named anywhere else
    const withoutRange = est.replace('qr.rangeFor(basket.exact, cfg)', '');
    assert.ok(!/exactTotal|\.exact\b|unitPrice|lineTotal|basket\.lines/.test(withoutRange), 'qrEstimate touches a figure it must never return');
  });
  it('qrSubmit returns the receipt only: ref, dates, and the rounded range the client was shown — never exactTotal or a line', () => {
    assert.match(sub, /estimate: pe\.shown \? \{ low: pe\.low, high: pe\.high \} : null \}/);
    const returns = [...sub.matchAll(/\breturn\s*\{[^\n]*/g)].map((m) => m[0]);
    for (const r of returns) assert.ok(!/exactTotal|basket\.exact|unitPrice|lines/.test(r), `a figure reaches a response: ${r}`);
  });
  it('transaction callbacks RETURN a verdict and never throw (STATUS 2026-09-26: a throw discards the staged writes)', () => {
    for (const body of [est, sub]) {
      let from = 0;
      for (;;) {
        const i = body.indexOf('db.runTransaction(async (tx) => {', from);
        if (i < 0) break;
        let depth = 0, j = body.indexOf('{', i + 30);
        const start = j;
        for (; j < body.length; j++) { if (body[j] === '{') depth++; else if (body[j] === '}') { depth--; if (depth === 0) break; } }
        const cb = body.slice(start, j);
        assert.ok(!/\bthrow\b/.test(cb), 'a throw inside a runTransaction callback');
        assert.ok(/return \{ outcome:/.test(cb), 'a transaction callback with no verdict');
        from = j;
      }
    }
  });
  it('the staff notification carries no senderUid (a system send, exempt from the per-sender push quota) and no exact figure', () => {
    const nb = block('async function qrNotifyStaff', 'exports.qrStartSession');
    assert.ok(!/senderUid\s*:/.test(nb));
    assert.ok(!/exactTotal|internal/.test(nb));
    assert.match(nb, /dedupKey: `qr_\$\{refNo\}_\$\{uid\}`/);
    assert.ok(!/partner|uidRole/i.test(nb), 'the notification carries no role special case (the retired partner-drop line is gone, PARTNER-REMOVAL-SPEC Phase 3)');
  });
  it('qrAdminDelete reads users/{uid}.role (not a custom claim) and allows only president / manager', () => {
    const del = src.slice(src.indexOf('exports.qrAdminDelete = functions'));
    assert.match(del, /collection\('users'\)\.doc\(uid\)\.get\(\)/);
    assert.match(del, /role !== 'president' && role !== 'manager'/);
    assert.ok(!/context\.auth\.token/.test(del));
  });
  it('each public callable rate-limits on BOTH its per-IP bucket and its IP-independent global bucket', () => {
    const start = block('exports.qrStartSession = functions', '// ── qrEstimate');
    assert.match(start, /qrIpBucketRef\(db, 'start', ipKey\)[\s\S]*qrGlobalBucketRef\(db, 'global_start'\)/);
    assert.match(est, /qrIpBucketRef\(db, 'estimate', ipKey\)[\s\S]*qrGlobalBucketRef\(db, 'global_estimate'\)/);
    assert.match(sub, /qrIpBucketRef\(db, 'submit', ipKey\)[\s\S]*qrGlobalBucketRef\(db, 'global_submit'\)/);
    for (const body of [start, est, sub]) assert.match(body, /cirRequireIpKey\(db, ipInfo\)/);
    // the rate-limit step comes BEFORE any Firestore work in each public callable
    assert.ok(est.indexOf('cirRateLimit(') < est.indexOf('runTransaction'));
    assert.ok(sub.indexOf('cirRateLimit(') < sub.indexOf('qrLoadProducts'));
  });
  it('the only product source is Firestore products + productMeta/config, through the published-id filter', () => {
    const lp = block('async function qrLoadProducts', '/** §5.4 step 11a');
    assert.match(lp, /collection\('products'\)\.limit\(1000\)/);
    assert.match(lp, /collection\('productMeta'\)\.doc\('config'\)/);
    assert.match(lp, /qr\.buildCatalogueIndex\(/);                          // the quotable fixed SKUs + the family primaries, nothing else
    assert.match(lp, /collection\('product_pricing'\)/);                    // the private option sheets, read here by the Admin SDK only
    assert.match(lp, /qr\.buildPricingIndex\(/);
    assert.match(lp, /byId\.size === 0/);
  });
  it('no raw product / price field is read in the qr glue outside qr-core (the figures come only from qr.computeBasket)', () => {
    const glue = src.slice(src.indexOf('//  Public quote request callables'));
    assert.ok(!/\.basePrice|\.priceAdder|\.pricePer|rateD100|rateH100/.test(glue), 'glue prices things itself');
  });
  it('resolveSalesAndPresidentUids is shared: CIR and QR both resolve recipients through it (no second copy of the three queries)', () => {
    assert.equal((src.match(/where\('role', '==', 'president'\)/g) || []).length >= 1, true);
    assert.equal((src.match(/async function resolveSalesAndPresidentUids/g) || []).length, 1);
    assert.match(src, /resolveSalesAndPresidentUids\(db, '\[cirSubmit\]'\)/);
    assert.match(src, /resolveSalesAndPresidentUids\(db, '\[qrSubmit\]'\)/);
  });
});

// ══════════════════════════ QUOTE <-> REQUEST LINK (QUOTE-BUILDER-CONFIGURATOR-SPEC §8.2) ══════════════════════════
// A quote filed from a website request (kind 'qr') or a project brief (kind 'cir') carries `sourceRef`; when the CLIENT answers it on /q/,
// respondToQuote (Admin SDK) writes the answer back onto THAT request. The status rule is the pure qr.requestStatusAfterResponse; the rest is glue.
// Mutation-tested (scratch copies): the rule demoting a converted request, un-archiving an archived one, advancing on changes_requested or on a
// near-miss spelling of "accepted"; the glue reading the ref from the client's payload, dropping the ref-shape guard or the kind allowlist,
// matching quotes[] by position instead of docId, touching the request when the mirror is stale, writing the request outside its own try/catch
// — each must fail here.
describe('requestStatusAfterResponse — the request follows the client\'s answer to a quote filed from it, and never backwards', () => {
  const OPEN = ['new', 'in_review', 'contacted', 'quoted'];     // quote_requests has no 'contacted'; the client_info_requests enum does — both advance the same way
  it('is a pure export of qr-core', () => {
    assert.equal(typeof Q.requestStatusAfterResponse, 'function');
    assert.equal(Q.requestStatusAfterResponse.length, 2);
  });
  it('an ACCEPTED quote moves a new / in_review / contacted / quoted request to converted', () => {
    for (const s of OPEN) assert.equal(Q.requestStatusAfterResponse(s, 'accepted'), 'converted', s);
  });
  it('an ACCEPTED quote never demotes or un-archives: converted and archived stay exactly as they are', () => {
    assert.equal(Q.requestStatusAfterResponse('converted', 'accepted'), 'converted');
    assert.equal(Q.requestStatusAfterResponse('archived', 'accepted'), 'archived');
  });
  it('CHANGES REQUESTED never changes the status, whatever it is', () => {
    for (const s of [...OPEN, 'converted', 'archived']) assert.equal(Q.requestStatusAfterResponse(s, 'changes_requested'), s, s);
  });
  it('only the exact word "accepted" is an acceptance — a near miss, a wrong case or junk leaves the status alone (fails closed)', () => {
    for (const r of ['accept', 'ACCEPTED', 'Accepted', ' accepted', 'needs_revision', 'declined', '', null, undefined, 0, 1, true, {}, []]) {
      for (const s of [...OPEN, 'converted', 'archived']) assert.equal(Q.requestStatusAfterResponse(s, r), s, `${JSON.stringify(r)} on ${s}`);
    }
  });
  it('is total: junk or a missing current status never throws, and an acceptance still converts anything that is not converted / archived', () => {
    for (const s of [undefined, null, '', 'weird', 5, {}]) {
      assert.doesNotThrow(() => Q.requestStatusAfterResponse(s, 'accepted'));
      assert.equal(Q.requestStatusAfterResponse(s, 'accepted'), 'converted');
      assert.equal(Q.requestStatusAfterResponse(s, 'changes_requested'), s);
    }
  });
});

describe('functions/index.js respondToQuote — writes the answer back onto the request the quote was filed from (§8.2) — source', () => {
  const src = read('functions/index.js');
  const a = src.indexOf('exports.respondToQuote = functions');
  const fnSrc = src.slice(a, src.indexOf('recordAttendancePunch', a));
  const b0 = fnSrc.indexOf('QUOTE-BUILDER-CONFIGURATOR-SPEC §8.2');
  const blk = fnSrc.slice(b0, fnSrc.indexOf('// Notify: quote creator + the president'));

  it('the block exists, once, inside respondToQuote', () => {
    assert.ok(a > 0 && b0 > 0, 'respondToQuote or its §8.2 block is missing');
    assert.equal((fnSrc.match(/QUOTE-BUILDER-CONFIGURATOR-SPEC §8\.2/g) || []).length, 1);
    assert.ok(blk.length > 400);
  });
  it('the ref comes from the QUOTE DOC (a staff-written field), never from the anonymous client\'s payload', () => {
    assert.match(blk, /const sref = qSnap\.data\(\)\.sourceRef;/);
    assert.ok(!/data\.sourceRef|data && data\.source|data\.ref\b|data\.kind\b/.test(fnSrc), 'the callable reads a request ref from the client payload');
  });
  it('the ref is shape-checked (QR-/CIR- + yymmdd + 6 chars) and the kind is an allowlist before it is ever used as a document id', () => {
    assert.ok(blk.includes('/^(QR|CIR)-\\d{6}-[A-Z0-9]{6}$/.test(sref.ref)'));
    assert.match(blk, /typeof sref\.ref === 'string'/);
    assert.match(blk, /\(sref\.kind === 'qr' \|\| sref\.kind === 'cir'\)/);
    assert.match(blk, /sref\.kind === 'qr' \? 'quote_requests' : 'client_info_requests'/);
  });
  it('the new status comes from the pure rule and is written only when it differs; the matching quotes[] entry is found by docId and takes the quote\'s own status', () => {
    assert.match(blk, /qr\.requestStatusAfterResponse\(existing\.status, newStatus\)/);
    assert.match(blk, /if \(nextStatus !== existing\.status\) patch\.status = nextStatus;/);
    assert.match(blk, /q\.docId === quoteId \? \{ \.\.\.q, status: internalStatus \} : q/);
    assert.match(blk, /updatedAt: admin\.firestore\.FieldValue\.serverTimestamp\(\)/);
    for (const k of ['statusChangedBy', 'convertedBy', 'convertedClientId']) assert.ok(!blk.includes(k), `the glue forges ${k}`);
  });
  it('it sits INSIDE the shareToken guard and after the internal quote update, before the notifications, in its OWN try/catch that only logs', () => {
    const guard = fnSrc.indexOf('qSnap.data().shareToken === token');
    const upd = fnSrc.indexOf('await qRef.update({');
    const notify = fnSrc.indexOf('// Notify: quote creator + the president');
    assert.ok(guard > 0 && guard < upd && upd < b0 && b0 < notify, 'wrong place in respondToQuote');
    assert.match(blk, /\btry \{[\s\S]*\} catch \(e\) \{\s*console\.error\('\[respondToQuote\] request link sync failed/);
    assert.ok(!/\bthrow\b/.test(blk), 'a throw in the best-effort block would fail the client\'s response');
  });
  it('the read-modify-write on the request is one transaction, and the callback returns without throwing when the request is gone', () => {
    assert.match(blk, /await db\.runTransaction\(async \(tx\) => \{/);
    assert.match(blk, /if \(!reqSnap\.exists\) return;/);
  });
});

describe('functions/index.js respondToQuote — the request follows the client\'s answer, against the in-memory Firestore', {
  skip: fs.existsSync(path.join(ROOT, 'functions', 'node_modules', 'firebase-functions', 'package.json')) ? false : 'functions/node_modules is not installed (firebase-functions missing)',
}, () => {
  const { createFake, FakeTimestamp } = require('./fixtures/fake-firestore.cjs');
  const fk = createFake();
  const TOKEN = 'abcd2345wxyz', QID = 'QdocId0001', REF = 'QR-261028-K7M2PX', CIR_REF = 'CIR-261028-AB23CD';
  let fns;
  function loadFns() {
    const idx = require.resolve('../functions/index.js');
    delete require.cache[idx];
    const orig = Module._load;
    Module._load = function (request) { if (request === 'firebase-admin') return fk.admin; return orig.apply(this, arguments); };
    try { return require(idx); } finally { Module._load = orig; }
  }
  const entry = (docId, over) => ({ docId, coll: 'bk_quotes', quoteNumber: 'BK-ML-WB-261028-001', version: 1, total: 123456, status: 'filed', filedAt: '2026-10-28T01:00:00.000Z', byName: 'Sales One', ...(over || {}) });
  const requestDoc = (over) => ({ refNo: REF, status: 'quoted', updatedAt: new FakeTimestamp(1000), quotes: [entry('Q0000OLD', { version: 1 }), entry(QID, { version: 2 })], ...(over || {}) });
  function seedAll(o) {
    o = o || {};
    fk.reset();
    fk.seed('users/u_pres', { role: 'president', displayName: 'Pres' });
    fk.seed('users/u_sales', { role: 'employee', department: 'Sales', displayName: 'Sales One' });
    fk.seed(`public_quotes/${TOKEN}`, { status: 'pending', clientResponse: { status: 'pending' }, src: { coll: 'bk_quotes', id: QID }, clientName: 'JDC Foods', quoteNumber: 'BK-ML-WB-261028-001', total: 123456 });
    fk.seed(`bk_quotes/${QID}`, { shareToken: TOKEN, createdBy: 'u_sales', status: 'sent', bankDetails: '', sourceRef: { kind: 'qr', ref: REF }, ...(o.quote || {}) });
    if (o.request !== null) fk.seed(`quote_requests/${REF}`, o.request || requestDoc());
    if (o.cir) fk.seed(`client_info_requests/${CIR_REF}`, o.cir);
  }
  const answer = (action, extra) => fns.respondToQuote.run({ token: TOKEN, action, name: 'Juan Dela Cruz', note: action === 'request_changes' ? 'Please add a second sink' : '', ...(extra || {}) }, {});
  beforeEach(() => { fns = loadFns(); });

  it('ACCEPT: the request becomes converted, the matching quotes[] entry becomes accepted, every other entry and field is untouched', async () => {
    seedAll();
    const r = await answer('accept');
    assert.equal(r.ok, true); assert.equal(r.status, 'accepted');
    const req = fk.read(`quote_requests/${REF}`);
    assert.equal(req.status, 'converted');
    assert.deepEqual(req.quotes.map((q) => [q.docId, q.status]), [['Q0000OLD', 'filed'], [QID, 'accepted']]);
    assert.deepEqual(req.quotes[0], entry('Q0000OLD', { version: 1 }), 'another quote\'s entry was edited');
    assert.equal(req.quotes[1].version, 2); assert.equal(req.quotes[1].total, 123456); assert.equal(req.quotes[1].quoteNumber, 'BK-ML-WB-261028-001');
    assert.ok(req.updatedAt instanceof FakeTimestamp && req.updatedAt.toMillis() !== 1000, 'updatedAt was not bumped');
    assert.deepEqual(Object.keys(req).sort(), ['quotes', 'refNo', 'status', 'updatedAt'], 'the glue wrote a field the spec does not name');
    assert.equal(fk.read(`bk_quotes/${QID}`).status, 'accepted');
    assert.equal(fk.list('notifications/u_sales/items').length, 1, 'the quote creator is still notified');
  });
  it('ACCEPT on a project brief (kind cir) converts a client_info_requests doc — including one that was only "contacted"', async () => {
    for (const from of ['quoted', 'contacted']) {
      seedAll({ quote: { sourceRef: { kind: 'cir', ref: CIR_REF } }, cir: requestDoc({ refNo: CIR_REF, status: from }), request: null });
      await answer('accept');
      assert.equal(fk.read(`client_info_requests/${CIR_REF}`).status, 'converted', from);
      assert.equal(fk.read(`client_info_requests/${CIR_REF}`).quotes[1].status, 'accepted');
      assert.ok(!fk.has(`quote_requests/${REF}`), 'a cir source touched quote_requests');
    }
  });
  it('REQUEST CHANGES: the request keeps its status, the matching entry becomes needs_revision', async () => {
    seedAll();
    const r = await answer('request_changes');
    assert.equal(r.status, 'changes_requested');
    const req = fk.read(`quote_requests/${REF}`);
    assert.equal(req.status, 'quoted');
    assert.deepEqual(req.quotes.map((q) => q.status), ['filed', 'needs_revision']);
    assert.equal(fk.read(`bk_quotes/${QID}`).status, 'needs_revision');
  });
  it('NEVER DEMOTED: an accepted quote leaves a converted or archived request in that status (its quotes[] entry still follows the quote)', async () => {
    for (const s of ['converted', 'archived']) {
      seedAll({ request: requestDoc({ status: s }) });
      await answer('accept');
      const req = fk.read(`quote_requests/${REF}`);
      assert.equal(req.status, s);
      assert.equal(req.quotes[1].status, 'accepted');
    }
  });
  it('a request that predates quotes[] (no array) still advances; no quotes field is invented', async () => {
    seedAll({ request: { refNo: REF, status: 'in_review', updatedAt: new FakeTimestamp(1000) } });
    await answer('accept');
    const req = fk.read(`quote_requests/${REF}`);
    assert.equal(req.status, 'converted');
    assert.ok(!('quotes' in req));
  });
  it('a junk entry inside quotes[] is carried through untouched and breaks nothing', async () => {
    seedAll({ request: requestDoc({ quotes: [null, 'x', 7, entry(QID)] }) });
    await answer('accept');
    const req = fk.read(`quote_requests/${REF}`);
    assert.deepEqual(req.quotes.slice(0, 3), [null, 'x', 7]);
    assert.equal(req.quotes[3].status, 'accepted');
  });
  it('a quote with no sourceRef (every quote filed before this feature) leaves every request alone and answers normally', async () => {
    seedAll({ quote: { sourceRef: null } });
    const before = fk.read(`quote_requests/${REF}`);
    const r = await answer('accept');
    assert.equal(r.ok, true);
    assert.deepEqual(fk.read(`quote_requests/${REF}`), before);
    assert.equal(fk.read(`bk_quotes/${QID}`).status, 'accepted');
  });
  it('a hostile or malformed sourceRef is ignored: bad shape, path tricks, wrong kind, wrong types — the request is untouched, the answer still lands', async () => {
    const hostile = [
      { kind: 'qr', ref: `${REF}/notes/n1` }, { kind: 'qr', ref: `../quote_requests/${REF}` }, { kind: 'qr', ref: REF.toLowerCase() },
      { kind: 'qr', ref: `${REF}\n` }, { kind: 'qr', ref: 'QR-261028-K7M2P' }, { kind: 'qr', ref: 'QR-26102-K7M2PX' }, { kind: 'qr', ref: 'XX-261028-K7M2PX' },
      { kind: 'users', ref: REF }, { kind: 'bk_quotes', ref: REF }, { kind: 'QR', ref: REF }, { kind: ['qr'], ref: REF }, { ref: REF }, { kind: 'qr' },
      { kind: 'qr', ref: 5 }, { kind: 'qr', ref: null }, { kind: 'qr', ref: [REF] }, REF, 7, true, [REF], [],
    ];
    for (const sourceRef of hostile) {
      seedAll({ quote: { sourceRef } });
      const before = fk.read(`quote_requests/${REF}`);
      const r = await answer('accept');
      assert.equal(r.ok, true, JSON.stringify(sourceRef));
      assert.deepEqual(fk.read(`quote_requests/${REF}`), before, `a request was touched through ${JSON.stringify(sourceRef)}`);
      assert.equal(fk.read(`bk_quotes/${QID}`).status, 'accepted', JSON.stringify(sourceRef));
    }
  });
  it('a kind that disagrees with the ref prefix only ever reads the collection the kind names (a missing doc there is a quiet no-op)', async () => {
    seedAll({ quote: { sourceRef: { kind: 'cir', ref: REF } } });
    const before = fk.read(`quote_requests/${REF}`);
    await answer('accept');
    assert.deepEqual(fk.read(`quote_requests/${REF}`), before);
    assert.ok(!fk.has(`client_info_requests/${REF}`), 'a doc was created by the link sync');
  });
  it('a request that no longer exists (deleted) is skipped without error and without creating it', async () => {
    seedAll({ request: null });
    const r = await answer('accept');
    assert.equal(r.ok, true);
    assert.ok(!fk.has(`quote_requests/${REF}`));
    assert.equal(fk.read(`bk_quotes/${QID}`).status, 'accepted');
  });
  it('a STALE mirror (the quote has since been re-shared under another token) touches neither the quote nor the request', async () => {
    seedAll({ quote: { shareToken: 'someOtherToken9' } });
    const before = fk.read(`quote_requests/${REF}`);
    const r = await answer('accept');
    assert.equal(r.ok, true);
    assert.deepEqual(fk.read(`quote_requests/${REF}`), before);
    assert.equal(fk.read(`bk_quotes/${QID}`).status, 'sent');
  });
  it('the anonymous caller cannot choose the request: a sourceRef / ref / kind inside the call payload is ignored', async () => {
    seedAll({ quote: { sourceRef: null }, cir: requestDoc({ refNo: CIR_REF }) });
    const before = fk.read(`quote_requests/${REF}`), beforeCir = fk.read(`client_info_requests/${CIR_REF}`);
    await answer('accept', { sourceRef: { kind: 'qr', ref: REF }, ref: REF, kind: 'cir', refNo: CIR_REF });
    assert.deepEqual(fk.read(`quote_requests/${REF}`), before);
    assert.deepEqual(fk.read(`client_info_requests/${CIR_REF}`), beforeCir);
  });
  it('a failure while updating the request is logged and NEVER reaches the client or the notifications', async () => {
    seedAll();
    const realTx = fk.db.runTransaction;
    let calls = 0;
    fk.db.runTransaction = async (fn) => { calls++; if (calls >= 2) throw new Error('request link boom'); return realTx(fn); };
    const logged = mock.method(console, 'error', () => {});
    try {
      const r = await answer('accept');
      assert.equal(r.ok, true); assert.equal(r.status, 'accepted');
      assert.equal(calls, 2, 'the link sync did not use a second transaction');
      assert.ok(logged.mock.calls.some((c) => /request link sync failed/.test(String(c.arguments[0])) && /request link boom/.test(String(c.arguments[1]))));
    } finally { logged.mock.restore(); fk.db.runTransaction = realTx; }
    assert.equal(fk.read(`bk_quotes/${QID}`).status, 'accepted', 'the quote itself was not flipped');
    assert.equal(fk.read(`quote_requests/${REF}`).status, 'quoted', 'the failed transaction left a partial write');
    assert.equal(fk.list('notifications/u_sales/items').length, 1, 'the notifications were skipped');
  });
  it('a second answer is still refused by the mirror\'s once-only guard and cannot re-touch the request', async () => {
    seedAll();
    await answer('accept');
    const after = fk.read(`quote_requests/${REF}`);
    await assert.rejects(answer('request_changes'), (e) => e.code === 'failed-precondition');
    assert.deepEqual(fk.read(`quote_requests/${REF}`), after);
  });
});

function resolveMaster() {
  for (const p of [path.join(ROOT, 'products-database.json'), path.join(os.homedir(), 'Desktop', 'barro-private', 'products-database.json')]) {
    if (fs.existsSync(p)) return p;
  }
  return null;
}
